  USING (((bucket_id = 'competency-certificates'::text) AND (split_part(name, '/'::text, 1) = (haven.organization_id())::text) AND haven.has_facility_access((split_part(name, '/'::text, 2))::uuid) AND ((haven.app_role() = ANY (ARRAY['owner'::app_role, 'org_admin'::app_role, 'facility_admin'::app_role, 'med_tech'::app_role])) OR (EXISTS ( SELECT 1
   FROM (competency_demonstrations cd
     JOIN staff s ON (((s.id = cd.staff_id) AND (s.deleted_at IS NULL))))
  WHERE ((cd.id = (split_part(objects.name, '/'::text, 3))::uuid) AND (cd.deleted_at IS NULL) AND (s.user_id = auth.uid())))) OR ((split_part(name, '/'::text, 3) = 'tc'::text) AND (EXISTS ( SELECT 1
   FROM (staff_training_completions stc
     JOIN staff s ON (((s.id = stc.staff_id) AND (s.deleted_at IS NULL))))
  WHERE ((stc.id = (split_part(objects.name, '/'::text, 4))::uuid) AND (stc.deleted_at IS NULL) AND (stc.organization_id = haven.organization_id()) AND (stc.facility_id = (split_part(objects.name, '/'::text, 2))::uuid) AND (s.user_id = auth.uid()))))))));
ALTER POLICY "incident_photos_storage_insert" ON "storage"."objects"
  WITH CHECK (((bucket_id = 'incident-photos'::text) AND (split_part(name, '/'::text, 1) = (haven.organization_id())::text) AND (
CASE
    WHEN (split_part(name, '/'::text, 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) THEN (split_part(name, '/'::text, 2))::uuid
    ELSE NULL::uuid
END IN ( SELECT haven.accessible_facility_ids() AS accessible_facility_ids)) AND (haven.app_role() = ANY (ARRAY['owner'::app_role, 'org_admin'::app_role, 'facility_admin'::app_role, 'manager'::app_role, 'admin_assistant'::app_role, 'coordinator'::app_role, 'med_tech'::app_role, 'caregiver'::app_role, 'med_tech'::app_role]))));
ALTER POLICY "incident_photos_storage_read" ON "storage"."objects"
  USING (((bucket_id = 'incident-photos'::text) AND (split_part(name, '/'::text, 1) = (haven.organization_id())::text) AND (
CASE
    WHEN (split_part(name, '/'::text, 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) THEN (split_part(name, '/'::text, 2))::uuid
    ELSE NULL::uuid
END IN ( SELECT haven.accessible_facility_ids() AS accessible_facility_ids)) AND (haven.app_role() = ANY (ARRAY['owner'::app_role, 'org_admin'::app_role, 'facility_admin'::app_role, 'manager'::app_role, 'admin_assistant'::app_role, 'coordinator'::app_role, 'med_tech'::app_role, 'caregiver'::app_role, 'med_tech'::app_role]))));

-- 55 functions (role_tier is written out by hand below)
CREATE OR REPLACE FUNCTION haven.assert_resident_bed_move_authority(p_organization_id uuid, p_facility_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor record; expiry text;
BEGIN
  SELECT * INTO actor FROM haven.current_authorized_actor() WHERE actor_is_managed;
  IF NOT FOUND OR auth.uid() IS NULL
    OR actor.actor_user_id IS DISTINCT FROM auth.uid()
    OR actor.actor_app_role NOT IN ('owner','org_admin','facility_admin','med_tech')
    OR actor.actor_organization_id IS DISTINCT FROM p_organization_id
    OR NOT haven.has_facility_access(p_facility_id) THEN
    RAISE EXCEPTION 'Current bed assignment authority required' USING ERRCODE='42501';
  END IF;
  -- PostgREST checks token expiry; retain it for authenticated direct SQL too.
  expiry := auth.jwt()->>'exp';
  IF expiry IS NOT NULL THEN
    IF expiry !~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'Current bed assignment authority required' USING ERRCODE='42501';
    END IF;
    IF expiry::numeric <= extract(epoch FROM clock_timestamp()) THEN
      RAISE EXCEPTION 'Current bed assignment authority required' USING ERRCODE='42501';
    END IF;
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION haven.assert_rounding_service_actor(p_actor_id uuid, p_actor_role text, p_session_id uuid, p_claim_version integer, p_organization_id uuid, p_facility_id uuid, p_manager_only boolean, p_require_staff boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_role text;
  v_organization uuid;
  v_version integer;
  v_has_grant boolean:=false;
  v_staff_id uuid;
BEGIN
  PERFORM 1 FROM public.facilities AS facility
  WHERE facility.id=p_facility_id AND facility.organization_id=p_organization_id AND facility.deleted_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Rounding actor is no longer authorized' USING ERRCODE='42501'; END IF;

  SELECT true INTO v_has_grant FROM public.user_facility_access AS access
  WHERE access.user_id=p_actor_id AND access.organization_id=p_organization_id
    AND access.facility_id=p_facility_id AND access.revoked_at IS NULL
  FOR SHARE;

  SELECT profile.app_role::text,profile.organization_id,profile.auth_claim_version
  INTO v_role,v_organization,v_version
  FROM public.user_profiles AS profile
  JOIN auth.users AS auth_user ON auth_user.id=profile.id
  JOIN auth.sessions AS session ON session.id=p_session_id AND session.user_id=profile.id
  WHERE profile.id=p_actor_id AND profile.is_active AND profile.deleted_at IS NULL
    AND auth_user.deleted_at IS NULL
    AND (auth_user.banned_until IS NULL OR auth_user.banned_until<=pg_catalog.now())
  FOR SHARE OF profile,auth_user,session;

  IF v_role IS NULL OR v_role IS DISTINCT FROM p_actor_role
     OR v_organization IS DISTINCT FROM p_organization_id
     OR (p_claim_version=v_version OR (p_claim_version IS NULL AND v_version=1)) IS NOT TRUE
     OR (p_manager_only AND v_role NOT IN('owner','org_admin','facility_admin','med_tech'))
     OR (v_role NOT IN('owner','org_admin') AND v_has_grant IS NOT TRUE) THEN
    RAISE EXCEPTION 'Rounding actor is no longer authorized' USING ERRCODE='42501';
  END IF;

  SELECT staff.id INTO v_staff_id FROM public.staff AS staff
  WHERE staff.user_id=p_actor_id AND staff.organization_id=p_organization_id
    AND staff.facility_id=p_facility_id AND staff.employment_status='active' AND staff.deleted_at IS NULL
  ORDER BY staff.id LIMIT 1 FOR SHARE;
  IF p_require_staff AND v_staff_id IS NULL THEN
    RAISE EXCEPTION 'An active staff profile is required' USING ERRCODE='42501';
  END IF;
  RETURN pg_catalog.jsonb_build_object('role',v_role,'staff_id',v_staff_id);
END $function$;

CREATE OR REPLACE FUNCTION haven.benefits_access_list_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a jsonb:=haven.benefits_actor(); BEGIN
 IF NOT (a->>'admin')::boolean THEN RAISE EXCEPTION 'Benefits grant administrator required' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('can_manage',true,
 'grants',coalesce((SELECT jsonb_agg(to_jsonb(g)||jsonb_build_object('user_name',p.full_name,'facility_name',f.name) ORDER BY g.updated_at DESC) FROM public.benefits_access_grants g JOIN public.user_profiles p ON p.id=g.user_id JOIN public.facilities f ON f.id=g.facility_id WHERE g.organization_id=(a->>'org')::uuid),'[]'),
 -- Candidate grant subjects come from actual facility access rows (plus admins), not a profile x facility cross join.
 'users',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (
  SELECT DISTINCT p.id,p.full_name name,f.id facility_id FROM public.user_profiles p
  JOIN public.facilities f ON f.organization_id=p.organization_id AND f.deleted_at IS NULL
  WHERE p.organization_id=(a->>'org')::uuid AND p.is_active AND p.deleted_at IS NULL
  AND p.app_role::text IN ('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech')
  AND (p.app_role::text IN ('owner','org_admin') OR EXISTS(SELECT 1 FROM public.user_facility_access u WHERE u.user_id=p.id AND u.facility_id=f.id AND u.organization_id=p.organization_id AND u.revoked_at IS NULL))
  AND haven.benefits_staff(p.id,p.organization_id,f.id) ORDER BY p.full_name,f.id LIMIT 1000) x),'[]'));
END $function$;

CREATE OR REPLACE FUNCTION haven.benefits_actor()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a record; BEGIN
 SELECT * INTO a FROM haven.current_authorized_actor();
 IF a.actor_user_id IS NULL OR NOT a.actor_is_managed OR a.actor_role_text NOT IN ('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech')
 OR EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.id=a.actor_user_id AND coalesce(p.settings->>'must_change_password','false')<>'false') THEN
 RAISE EXCEPTION 'Benefits actor unavailable' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('id',a.actor_user_id,'org',a.actor_organization_id,'admin',a.actor_role_text IN ('owner','org_admin'));
END $function$;

CREATE OR REPLACE FUNCTION haven.benefits_staff(p_user uuid, p_org uuid, p_facility uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS(SELECT 1 FROM public.user_profiles p JOIN auth.users u ON u.id=p.id
 WHERE p.id=p_user AND p.organization_id=p_org AND p.is_active AND p.deleted_at IS NULL AND u.deleted_at IS NULL
 AND (u.banned_until IS NULL OR u.banned_until<=now()) AND p.app_role::text IN ('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech')
 AND coalesce(p.settings->>'must_change_password','false')='false'
 AND (p.app_role::text IN ('owner','org_admin') OR (
 EXISTS(SELECT 1 FROM public.user_facility_access a WHERE a.user_id=p.id AND a.facility_id=p_facility AND a.organization_id=p_org AND a.revoked_at IS NULL)
 AND EXISTS(SELECT 1 FROM public.staff s WHERE s.user_id=p.id AND s.organization_id=p_org AND s.deleted_at IS NULL AND s.employment_status='active'
 AND (s.termination_date IS NULL OR s.termination_date>current_date) AND (s.facility_id=p_facility OR EXISTS(
 SELECT 1 FROM public.staff_facility_assignments x WHERE x.staff_id=s.id AND x.organization_id=p_org AND x.facility_id=p_facility AND x.deleted_at IS NULL AND x.start_date<=current_date AND (x.end_date IS NULL OR x.end_date>=current_date)))))));
$function$;

