CREATE OR REPLACE FUNCTION haven.complete_operation_task_review(p_task_id uuid, p_actor_id uuid, p_actor_role text, p_notes text, p_evidence text[] DEFAULT '{}'::text[])
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  t public.operation_task_instances%ROWTYPE;
  target text;
  finalizer uuid;
  v_current_role text;
  v_current_organization uuid;
BEGIN
  PERFORM haven.lock_operation_authority(p_task_id);
  IF p_actor_id IS DISTINCT FROM auth.uid() OR p_actor_role IS DISTINCT FROM haven.app_role()::text THEN
    RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501';
  END IF;
  SELECT * INTO STRICT t FROM public.operation_task_instances
  WHERE id=p_task_id AND deleted_at IS NULL FOR UPDATE;
  -- COL-142: managed occurrences are recorded through the receipt command.
  IF t.occurrence_kind IS NOT NULL THEN RAISE EXCEPTION 'Managed occurrences are recorded through the receipt command' USING ERRCODE='P0001'; END IF;
  SELECT profile.app_role::text,profile.organization_id
  INTO v_current_role,v_current_organization
  FROM public.user_profiles AS profile
  WHERE profile.id=p_actor_id AND profile.is_active AND profile.deleted_at IS NULL
  FOR SHARE;
  IF v_current_role IS NULL OR v_current_organization IS DISTINCT FROM t.organization_id
     OR v_current_role IS DISTINCT FROM p_actor_role
     OR (
       t.assigned_to=p_actor_id
       OR (t.assigned_to IS NULL AND t.assigned_role=v_current_role)
       OR v_current_role IN('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role')
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'Task actor is no longer authorized' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM public.facilities AS facility
  WHERE facility.id=t.facility_id AND facility.organization_id=v_current_organization AND facility.deleted_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task actor is no longer authorized' USING ERRCODE='42501';
  END IF;
  IF v_current_role NOT IN('owner','org_admin') THEN
    PERFORM 1 FROM public.user_facility_access AS access
    WHERE access.user_id=p_actor_id AND access.organization_id=v_current_organization
      AND access.facility_id=t.facility_id AND access.revoked_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Task actor is no longer authorized' USING ERRCODE='42501';
    END IF;
  END IF;
  IF coalesce(cardinality(p_evidence),0)>0 THEN RAISE EXCEPTION 'Classified evidence command required' USING ERRCODE='42501'; END IF;
  IF t.status='completed' THEN RETURN 'completed'; END IF;
  IF t.status NOT IN('pending','in_progress','missed','deferred') THEN RAISE EXCEPTION 'Task cannot be completed from this state'; END IF;
  IF t.signed_by IS NOT NULL AND t.requires_dual_sign THEN
    IF t.signed_by=p_actor_id THEN RAISE EXCEPTION 'A different authorized staff member must verify this task'; END IF;
    target:='completed'; finalizer:=p_actor_id;
  ELSE
    target:=CASE WHEN t.requires_dual_sign THEN 'in_progress' ELSE 'completed' END;
    finalizer:=CASE WHEN t.requires_dual_sign THEN NULL ELSE p_actor_id END;
  END IF;
  UPDATE public.operation_task_instances SET status=target,signed_by=coalesce(t.signed_by,p_actor_id),
    signed_at=coalesce(t.signed_at,now()),second_sign_by=CASE WHEN t.requires_dual_sign THEN finalizer END,
    second_signed_at=CASE WHEN t.requires_dual_sign AND finalizer IS NOT NULL THEN now() END,
    completed_at=coalesce(t.completed_at,now()),
    completion_notes=CASE WHEN t.signed_by IS NULL THEN p_notes ELSE t.completion_notes END,
    completion_evidence_paths=CASE WHEN t.signed_by IS NULL THEN p_evidence ELSE t.completion_evidence_paths END,
    verified_by=finalizer,verified_at=CASE WHEN finalizer IS NOT NULL THEN now() END,
    sla_met=(t.due_at IS NULL OR t.due_at>=coalesce(t.completed_at,now())),updated_by=p_actor_id
  WHERE id=t.id;
  INSERT INTO public.operation_audit_log(organization_id,facility_id,task_instance_id,event_type,from_status,to_status,actor_id,actor_role,event_notes,event_data)
  VALUES(t.organization_id,t.facility_id,t.id,'completed',t.status,target,p_actor_id,v_current_role,p_notes,
    jsonb_build_object('awaiting_second_verification',finalizer IS NULL,'independent_verification',t.signed_by IS NOT NULL));
  PERFORM haven.lock_operation_authority(p_task_id);
  RETURN CASE WHEN target='in_progress' THEN 'awaiting_verification' ELSE target END;
END $function$;

CREATE OR REPLACE FUNCTION haven.complete_rounding_task_core(p_task_id uuid, p_actor_id uuid, p_actor_role text, p_session_id uuid, p_claim_version integer, p_organization_id uuid, p_facility_id uuid, p_actual_staff_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_task public.resident_observation_tasks%ROWTYPE;
  v_actor jsonb;
  v_role text;
  v_staff_id uuid;
  v_has_active_assignment boolean;
  v_is_active_assignee boolean;
  v_log_id uuid;
  v_status public.resident_observation_task_status;
BEGIN
  SELECT * INTO STRICT v_task FROM public.resident_observation_tasks
  WHERE id=p_task_id AND organization_id=p_organization_id AND facility_id=p_facility_id AND deleted_at IS NULL
  FOR UPDATE;
  v_actor:=haven.assert_rounding_service_actor(p_actor_id,p_actor_role,p_session_id,p_claim_version,
    p_organization_id,p_facility_id,false,true);
  v_role:=v_actor->>'role';
  v_staff_id:=(v_actor->>'staff_id')::uuid;
  IF v_staff_id IS DISTINCT FROM p_actual_staff_id THEN
    RAISE EXCEPTION 'Rounding actor staff identity changed' USING ERRCODE='42501';
  END IF;

  PERFORM 1 FROM public.resident_observation_assignments AS assignment
  WHERE assignment.task_id=v_task.id AND assignment.organization_id=p_organization_id
    AND assignment.facility_id=p_facility_id AND assignment.released_at IS NULL
  ORDER BY assignment.id FOR SHARE;
  SELECT EXISTS(SELECT 1 FROM public.resident_observation_assignments AS assignment
      WHERE assignment.task_id=v_task.id AND assignment.organization_id=p_organization_id
        AND assignment.facility_id=p_facility_id AND assignment.released_at IS NULL),
    EXISTS(SELECT 1 FROM public.resident_observation_assignments AS assignment
      WHERE assignment.task_id=v_task.id AND assignment.organization_id=p_organization_id
        AND assignment.facility_id=p_facility_id AND assignment.released_at IS NULL
        AND assignment.staff_id=v_staff_id)
  INTO v_has_active_assignment,v_is_active_assignee;

  -- Assignee guard, unchanged from the approved 327 body. `IS NOT TRUE` rather
  -- than `NOT (...)` is deliberate: an unassigned task compares NULL, and NULL
  -- must refuse rather than pass. supabase/tests/review_authoritative_actor.sql
  -- asserts a caregiver cannot complete a task whose assigned_staff_id is null
  -- and whose assignment rows are all released. That tested invariant outranks
  -- the spec's facility pool wording; see the build notes, decision D12.
  IF v_role NOT IN('owner','org_admin','facility_admin','med_tech')
     AND (CASE WHEN v_has_active_assignment THEN v_is_active_assignee ELSE v_task.assigned_staff_id=v_staff_id END) IS NOT TRUE THEN
    RAISE EXCEPTION 'Rounding task assignee changed' USING ERRCODE='42501';
  END IF;
  IF v_task.status IN('completed_on_time','completed_late','excused') THEN
    RAISE EXCEPTION 'Observation task is no longer completable' USING ERRCODE='P0001';
  END IF;
  v_status:=(p_payload->>'completion_status')::public.resident_observation_task_status;
  IF v_status NOT IN('completed_on_time','completed_late') THEN
    RAISE EXCEPTION 'Invalid completion status' USING ERRCODE='22023';
  END IF;

  PERFORM haven.require_observation_capture(p_task_id,p_payload);

  INSERT INTO public.resident_observation_logs(
    organization_id,entity_id,facility_id,resident_id,task_id,assigned_staff_id,staff_id,
    observed_at,entered_at,entry_mode,quick_status,resident_location,resident_position,resident_state,
    distress_present,breathing_concern,pain_concern,toileting_assisted,hydration_offered,repositioned,
    skin_concern_observed,fall_hazard_observed,refused_assistance,intervention_codes,exception_present,
    note,late_reason,composed_summary,chip_selections,created_by
  ) VALUES(
    v_task.organization_id,v_task.entity_id,v_task.facility_id,v_task.resident_id,v_task.id,
    v_task.assigned_staff_id,v_staff_id,(p_payload->>'observed_at')::timestamptz,
    (p_payload->>'entered_at')::timestamptz,(p_payload->>'entry_mode')::public.resident_observation_entry_mode,
    (p_payload->>'quick_status')::public.resident_observation_quick_status,p_payload->>'resident_location',
    p_payload->>'resident_position',p_payload->>'resident_state',
    coalesce((p_payload->>'distress_present')::boolean,false),coalesce((p_payload->>'breathing_concern')::boolean,false),
    coalesce((p_payload->>'pain_concern')::boolean,false),coalesce((p_payload->>'toileting_assisted')::boolean,false),
    coalesce((p_payload->>'hydration_offered')::boolean,false),coalesce((p_payload->>'repositioned')::boolean,false),
    coalesce((p_payload->>'skin_concern_observed')::boolean,false),coalesce((p_payload->>'fall_hazard_observed')::boolean,false),
    coalesce((p_payload->>'refused_assistance')::boolean,false),ARRAY(SELECT pg_catalog.jsonb_array_elements_text(
      coalesce(p_payload->'intervention_codes','[]'::jsonb))),coalesce((p_payload->>'exception_present')::boolean,false),
    p_payload->>'note',p_payload->>'late_reason',
    nullif(btrim(p_payload->>'composed_summary'),''),coalesce(p_payload->'chip_selections','{}'::jsonb),p_actor_id
  ) RETURNING id INTO v_log_id;

  IF nullif(p_payload->>'exception_type','') IS NOT NULL THEN
    INSERT INTO public.resident_observation_exceptions(
      organization_id,entity_id,facility_id,resident_id,log_id,exception_type,severity,requires_follow_up,follow_up_status
    ) VALUES(v_task.organization_id,v_task.entity_id,v_task.facility_id,v_task.resident_id,v_log_id,
      (p_payload->>'exception_type')::public.resident_observation_exception_type,
      coalesce(nullif(p_payload->>'exception_severity',''),'medium')::public.resident_observation_severity,true,'open');
  END IF;

  UPDATE public.resident_observation_tasks SET status=v_status,completed_log_id=v_log_id,updated_by=p_actor_id
  WHERE id=v_task.id;
  RETURN pg_catalog.jsonb_build_object('log_id',v_log_id,'status',v_status::text);
END $function$;

CREATE OR REPLACE FUNCTION haven.create_operation_manual_occurrence(p_activity uuid, p_facility uuid, p_subject uuid, p_request_key text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE activity public.operation_activities; subject public.operation_activity_subjects; f public.facilities; v public.operation_requirement_versions; fr public.operation_facility_requirements;
 k text; org uuid:=haven.organization_id(); class text; queue date; shift text; note text; request_hash text; existing public.operation_task_instances; row public.operation_task_instances;
 site_tz text; local_start timestamptz; local_end timestamptz; governing timestamptz; roles public.app_role[]; today date;
BEGIN
 IF p_request_key IS NULL OR p_request_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$' THEN RAISE EXCEPTION 'A request key is required' USING ERRCODE='22023'; END IF;
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Manual occurrence payload must be an object' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT * FROM jsonb_object_keys(p_payload) LOOP
  IF k NOT IN('queue_date','shift','note') THEN RAISE EXCEPTION 'Manual occurrence field is not editable' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF p_payload ? 'queue_date' AND jsonb_typeof(p_payload->'queue_date')<>'null' AND NOT haven.operation_schedule_date_valid(p_payload->'queue_date') THEN RAISE EXCEPTION 'queue_date must be a calendar date' USING ERRCODE='22023'; END IF;
 IF p_payload ? 'shift' AND jsonb_typeof(p_payload->'shift')<>'null' AND (jsonb_typeof(p_payload->'shift')<>'string' OR (p_payload->>'shift') NOT IN('day','evening','night')) THEN RAISE EXCEPTION 'shift must be day, evening or night' USING ERRCODE='22023'; END IF;
 IF p_payload ? 'note' AND jsonb_typeof(p_payload->'note')<>'null' AND (jsonb_typeof(p_payload->'note')<>'string' OR length(p_payload->>'note')>2000) THEN RAISE EXCEPTION 'note must be text of at most 2000 characters' USING ERRCODE='22023'; END IF;
 SELECT * INTO f FROM public.facilities WHERE id=p_facility AND organization_id=org AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF;
 -- Site authority before any activity or subject is read.
 PERFORM haven.lock_operation_recorder(org,p_facility);
 site_tz:=coalesce(f.timezone,'America/New_York');
 today:=(clock_timestamp() AT TIME ZONE site_tz)::date;
 queue:=coalesce((p_payload->>'queue_date')::date,today); shift:=nullif(p_payload->>'shift',''); note:=nullif(btrim(coalesce(p_payload->>'note','')),'');
 IF queue<today-366 OR queue>today+366 THEN RAISE EXCEPTION 'Queue date must be within a year of today' USING ERRCODE='22023'; END IF;
 SELECT * INTO activity FROM public.operation_activities WHERE id=p_activity AND organization_id=org AND (facility_id IS NULL OR facility_id=p_facility) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF;
 IF activity.subject_kind IS NULL THEN RAISE EXCEPTION 'activity subject classification is required before recording' USING ERRCODE='22023'; END IF;
 SELECT * INTO subject FROM public.operation_activity_subjects WHERE id=p_subject AND organization_id=org AND facility_id=p_facility FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF;
 IF subject.subject_kind<>activity.subject_kind THEN RAISE EXCEPTION 'Occurrence subject must match the activity subject' USING ERRCODE='22023'; END IF;
 class:=CASE subject.subject_kind WHEN 'employee' THEN 'employee_personnel' ELSE subject.subject_kind END;
 IF subject.subject_kind='resident' THEN PERFORM 1 FROM public.residents WHERE id=subject.resident_id FOR SHARE;
 ELSIF subject.subject_kind='employee' THEN PERFORM 1 FROM public.staff WHERE id=subject.employee_id FOR SHARE;
 ELSIF subject.subject_kind='asset' THEN PERFORM 1 FROM public.facility_assets WHERE id=subject.asset_id FOR SHARE; END IF;
 PERFORM haven.lock_operation_recorder(org,p_facility);
 governing:=clock_timestamp();
 SELECT * INTO v FROM public.operation_requirement_versions WHERE id=haven.operation_requirement_in_force(activity.id,governing) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'No requirement version is in force for this activity' USING ERRCODE='22023'; END IF;
 SELECT * INTO fr FROM public.operation_facility_requirements WHERE id=haven.operation_facility_requirement_in_force(activity.id,p_facility,governing) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'No site configuration is in force for this activity' USING ERRCODE='22023'; END IF;
 IF fr.applicability='not_applicable' THEN RAISE EXCEPTION 'This activity is not applicable at this site' USING ERRCODE='22023'; END IF;
 IF fr.requirement_version_id IS NOT NULL AND fr.requirement_version_id<>v.id THEN RAISE EXCEPTION 'Site configuration does not agree with the version in force' USING ERRCODE='22023'; END IF;
 local_start:=(queue::timestamp) AT TIME ZONE site_tz; local_end:=((queue+1)::timestamp) AT TIME ZONE site_tz;
 IF v.effective_from>=local_end OR (v.effective_to IS NOT NULL AND v.effective_to<=local_start) OR fr.effective_from>=local_end OR (fr.effective_to IS NOT NULL AND fr.effective_to<=local_start) THEN
  RAISE EXCEPTION 'Queue date lies outside the governing configuration window' USING ERRCODE='22023'; END IF;
 -- Recorder rule: the site list governs when set, else the central list; protected
 -- subjects additionally need an explicit recording grant (COL-133).
 roles:=coalesce(fr.local_allowed_recorder_roles,v.allowed_recorder_roles);
 IF NOT (haven.app_role()=ANY(roles)) THEN RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF;
 IF NOT haven.operation_subject_accessible(p_subject,org,p_facility,class)
  OR (class NOT IN('facility','asset') AND NOT EXISTS(SELECT 1 FROM public.operation_subject_access g WHERE g.user_id=auth.uid() AND g.organization_id=org AND g.facility_id=p_facility
   AND g.scope=class AND g.can_record AND g.revoked_at IS NULL AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp())))
  OR (class='resident' AND haven.app_role()::text NOT IN('owner','org_admin','facility_admin','med_tech')) THEN
  RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF;
 request_hash:=encode(sha256(convert_to(jsonb_build_object('activity',p_activity,'facility',p_facility,'subject',p_subject,'queue_date',to_char(queue,'YYYY-MM-DD'),'shift',shift,'note',note)::text,'UTF8')),'hex');
 SELECT * INTO existing FROM public.operation_task_instances WHERE request_key=p_request_key;
 IF FOUND THEN
  IF existing.request_hash=request_hash AND existing.created_by=auth.uid() THEN RETURN to_jsonb(existing)||jsonb_build_object('replayed',true); END IF;
  RAISE EXCEPTION 'This request was already saved with different content' USING ERRCODE='P0001';
 END IF;
 PERFORM set_config('haven.operation_occurrence_command',haven.operation_occurrence_token(),true);
 BEGIN
  INSERT INTO public.operation_task_instances(organization_id,facility_id,activity_id,subject_id,authority_class,template_name,template_category,template_cadence_type,
   assigned_shift_date,assigned_shift,assigned_role,status,priority,license_threatening,requires_dual_sign,requirement_version_id,facility_requirement_id,governing_at,
   schedule_snapshot,occurrence_kind,request_key,request_hash,completion_notes)
  VALUES(org,p_facility,activity.id,p_subject,class,coalesce(v.title,activity.name),'compliance','on_demand',queue,shift,haven.app_role()::text,'pending','normal',false,v.review_required,v.id,fr.id,governing,
   jsonb_build_object('evaluator_version','hfo-evaluator/1','queue_date_is_compatibility_only',true,'queue_date',to_char(queue,'YYYY-MM-DD'),'timezone',site_tz,'configuration_id',fr.id,'requirement_version_id',v.id,'note',note),
   'manual',p_request_key,request_hash,NULL) RETURNING * INTO row;
 EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'This request was already saved with different content' USING ERRCODE='P0001';
 END;
 INSERT INTO public.operation_audit_log(organization_id,facility_id,task_instance_id,event_type,to_status,actor_id,actor_role,event_notes,event_data)
 VALUES(org,p_facility,row.id,'created','pending',auth.uid(),haven.app_role()::text,note,jsonb_build_object('occurrence_kind','manual','request_key',p_request_key,'request_hash',request_hash,'queue_date_is_compatibility_only',true));
 PERFORM set_config('haven.operation_occurrence_command','',true);
 PERFORM haven.lock_operation_recorder(org,p_facility);
 RETURN to_jsonb(row)||jsonb_build_object('replayed',false);
END $function$;

CREATE OR REPLACE FUNCTION haven.defer_operation_task_review(p_task_id uuid, p_actor_id uuid, p_actor_role text, p_deferred_until timestamp with time zone, p_cancellation_reason text, p_request_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  t public.operation_task_instances%ROWTYPE;
  v_current_role text;
  v_current_organization uuid;
  v_reason text;
  v_request_hash text;
  v_expected_key text;
  v_replacement_id uuid;
  v_shift_date date;
  v_shift text;
BEGIN
  PERFORM haven.lock_operation_authority(p_task_id);
  IF p_actor_id IS DISTINCT FROM auth.uid() OR p_actor_role IS DISTINCT FROM haven.app_role()::text THEN
    RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501';
  END IF;
  SELECT * INTO STRICT t FROM public.operation_task_instances
  WHERE id=p_task_id AND deleted_at IS NULL FOR UPDATE;
  -- COL-139: a managed occurrence keeps its period identity; the legacy defer
  -- would create a replacement row without one.
  IF t.occurrence_kind IS NOT NULL THEN
    RAISE EXCEPTION 'Managed occurrences cannot be deferred by the legacy command' USING ERRCODE='P0001';
  END IF;

  SELECT profile.app_role::text,profile.organization_id
  INTO v_current_role,v_current_organization
  FROM public.user_profiles AS profile
  WHERE profile.id=p_actor_id AND profile.is_active AND profile.deleted_at IS NULL
  FOR SHARE;
  IF v_current_role IS NULL OR v_current_organization IS DISTINCT FROM t.organization_id
     OR v_current_role IS DISTINCT FROM p_actor_role
     OR (
       t.assigned_to=p_actor_id
       OR (t.assigned_to IS NULL AND t.assigned_role=v_current_role)
       OR v_current_role IN('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role')
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'Task actor is no longer authorized' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM public.facilities AS facility
  WHERE facility.id=t.facility_id AND facility.organization_id=v_current_organization AND facility.deleted_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task actor is no longer authorized' USING ERRCODE='42501'; END IF;
  IF v_current_role NOT IN('owner','org_admin') THEN
    PERFORM 1 FROM public.user_facility_access AS access
    WHERE access.user_id=p_actor_id AND access.organization_id=v_current_organization
      AND access.facility_id=t.facility_id AND access.revoked_at IS NULL
    FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Task actor is no longer authorized' USING ERRCODE='42501'; END IF;
  END IF;

  v_reason:=coalesce(nullif(trim(p_cancellation_reason),''),'Deferred to a later queue date');
  v_expected_key:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
    'operation-defer-v1:'||p_actor_id::text||':'||p_task_id::text,'UTF8'
  )),'hex');
  IF p_request_key IS DISTINCT FROM v_expected_key THEN
    RAISE EXCEPTION 'Invalid defer request key' USING ERRCODE='22023';
  END IF;
  v_request_hash:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
    'task_id',p_task_id,'actor_id',p_actor_id,'deferred_until',p_deferred_until,'reason',v_reason
  )::text,'UTF8')),'hex');

  IF t.defer_request_key IS NOT NULL THEN
    IF t.defer_request_key=p_request_key AND t.defer_request_hash=v_request_hash
       AND t.deferred_replacement_task_id IS NOT NULL THEN
      RETURN jsonb_build_object('new_task_id',t.deferred_replacement_task_id,'replayed',true);
    END IF;
    RAISE EXCEPTION 'This defer request was already saved with different content. Refresh the task before retrying';
  END IF;
  IF p_deferred_until IS NULL OR p_deferred_until<=pg_catalog.clock_timestamp() THEN
    RAISE EXCEPTION 'Deferred time must be in the future';
  END IF;
  IF t.status NOT IN('pending','in_progress','missed') THEN
    RAISE EXCEPTION 'Task cannot be deferred from this state';
  END IF;

  v_shift_date:=(p_deferred_until AT TIME ZONE 'America/New_York')::date;
  v_shift:=CASE
    WHEN extract(hour FROM p_deferred_until AT TIME ZONE 'America/New_York') BETWEEN 7 AND 14 THEN 'day'
    WHEN extract(hour FROM p_deferred_until AT TIME ZONE 'America/New_York') BETWEEN 15 AND 22 THEN 'evening'
    ELSE 'night'
  END;
  INSERT INTO public.operation_task_instances(
    organization_id,facility_id,template_id,template_name,template_category,template_cadence_type,
    assigned_shift_date,assigned_shift,assigned_to,assigned_role,status,priority,license_threatening,
    estimated_minutes,requires_dual_sign,due_at,created_by,updated_by,subject_id,authority_class
  ) VALUES(
    t.organization_id,t.facility_id,t.template_id,t.template_name,t.template_category,t.template_cadence_type,
    v_shift_date,v_shift,t.assigned_to,t.assigned_role,'pending',t.priority,t.license_threatening,
    t.estimated_minutes,t.requires_dual_sign,p_deferred_until,p_actor_id,p_actor_id,t.subject_id,t.authority_class
  ) RETURNING id INTO v_replacement_id;

  UPDATE public.operation_task_instances SET
    status='deferred',deferred_until=p_deferred_until,cancellation_reason=v_reason,
    defer_request_key=p_request_key,defer_request_hash=v_request_hash,
    deferred_replacement_task_id=v_replacement_id,updated_at=now(),updated_by=p_actor_id
  WHERE id=t.id;

  INSERT INTO public.operation_audit_log(
    organization_id,facility_id,task_instance_id,event_type,from_status,to_status,
    actor_id,actor_role,event_notes,event_data
  ) VALUES(
    t.organization_id,t.facility_id,t.id,'deferred',t.status,'deferred',
    p_actor_id,v_current_role,v_reason,jsonb_build_object(
      'deferred_to',p_deferred_until,'new_task_id',v_replacement_id,'source','admin-operations',
      'request_key',p_request_key,'request_hash',v_request_hash,'receipt_version',1
    )
  );
  PERFORM haven.lock_operation_authority(p_task_id);
  RETURN jsonb_build_object('new_task_id',v_replacement_id,'replayed',false);
END $function$;

CREATE OR REPLACE FUNCTION haven.effective_onboarding_organization_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT actor.actor_organization_id FROM haven.current_authorized_actor() AS actor
  WHERE actor.actor_role_text IN ('onboarding','owner','org_admin','facility_admin','med_tech','dietary', 'cook','maintenance_role','broker') LIMIT 1
$function$;

CREATE OR REPLACE FUNCTION haven.employee_record_readable(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS(SELECT 1 FROM public.employee_file_records r JOIN public.employee_file_requirements q ON q.id=r.requirement_id JOIN public.staff s ON s.id=r.staff_id
 WHERE r.id=p_id AND r.deleted_at IS NULL AND s.deleted_at IS NULL AND haven.employee_scope(r.organization_id,r.facility_id)
 AND CASE WHEN q.category='medical' THEN s.user_id=auth.uid() OR haven.employee_medical_reader(r.organization_id,r.facility_id)
 ELSE s.user_id=auth.uid() OR haven.employee_manager()
 OR (haven.app_role()::text='med_tech' AND q.required_signers && ARRAY['trainer','witness']::text[])
 OR (haven.app_role()::text='coordinator' AND 'witness'=ANY(q.required_signers)) END)
$function$;

CREATE OR REPLACE FUNCTION haven.lock_operation_help_handover(p_activity uuid, p_facility uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE org uuid; BEGIN
 -- Serialize the scope before checking current authority, including first writes.
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_activity::text||':'||p_facility::text,153));
 SELECT organization_id INTO org FROM public.operation_activities WHERE id=p_activity AND (facility_id IS NULL OR facility_id=p_facility) AND (origin='admin_log' OR (subject_kind='facility' AND facility_id=p_facility AND EXISTS(SELECT 1 FROM public.operation_task_templates t WHERE t.activity_id=p_activity AND t.deleted_at IS NULL AND haven.operation_template_links_accessible(t.organization_id,t.facility_id,t.linked_document_id,t.asset_ref,t.vendor_booking_ref)))) FOR SHARE;
 PERFORM haven.lock_operation_recorder(org,p_facility);
 IF org IS NULL OR NOT EXISTS(SELECT 1 FROM public.facilities WHERE id=p_facility AND organization_id=org AND deleted_at IS NULL)
 OR haven.app_role()::text NOT IN('housekeeper','owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role') THEN
 RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF; RETURN org;
END $function$;

CREATE OR REPLACE FUNCTION haven.lock_operation_work_authority(p_task uuid, p_roles app_role[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.operation_task_instances; s public.operation_activity_subjects; linked public.operation_task_templates; actor record;
BEGIN
 SELECT * INTO t FROM public.operation_task_instances WHERE id=p_task AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501'; END IF;
 IF t.template_id IS NOT NULL THEN
  SELECT * INTO linked FROM public.operation_task_templates WHERE id=t.template_id FOR SHARE;
  IF linked.asset_ref IS NOT NULL THEN PERFORM 1 FROM public.facility_assets WHERE id=linked.asset_ref FOR SHARE; END IF;
  IF linked.vendor_booking_ref IS NOT NULL THEN
   PERFORM 1 FROM public.vendors WHERE id=linked.vendor_booking_ref FOR SHARE;
   PERFORM 1 FROM public.vendor_facilities WHERE vendor_id=linked.vendor_booking_ref AND facility_id=t.facility_id FOR SHARE;
  END IF;
 END IF;
 SELECT * INTO s FROM public.operation_activity_subjects WHERE id=t.subject_id;
 IF s.subject_kind='resident' THEN PERFORM 1 FROM public.residents WHERE id=s.resident_id FOR SHARE;
 ELSIF s.subject_kind='employee' THEN PERFORM 1 FROM public.staff WHERE id=s.employee_id FOR SHARE;
 ELSIF s.subject_kind='asset' THEN PERFORM 1 FROM public.facility_assets WHERE id=s.asset_id FOR SHARE; END IF;
 PERFORM 1 FROM public.facilities WHERE id=t.facility_id FOR SHARE;
 PERFORM 1 FROM public.user_facility_access WHERE user_id=auth.uid() AND facility_id=t.facility_id FOR SHARE;
 PERFORM 1 FROM public.operation_subject_access WHERE user_id=auth.uid() AND facility_id=t.facility_id FOR SHARE;
 PERFORM 1 FROM public.employee_medical_access WHERE user_id=auth.uid() AND facility_id=t.facility_id FOR SHARE;
 PERFORM 1 FROM public.user_profiles p JOIN auth.users u ON u.id=p.id
  JOIN auth.sessions session ON session.user_id=p.id AND session.id=nullif(auth.jwt()->>'session_id','')::uuid
  WHERE p.id=auth.uid() FOR SHARE OF p,u,session;
 SELECT * INTO actor FROM haven.current_authorized_actor();
 IF actor.actor_is_managed IS NOT TRUE OR NOT haven.operation_task_readable(p_task)
  OR NOT (t.authority_class IN('facility','asset') OR EXISTS(SELECT 1 FROM public.operation_subject_access g WHERE g.user_id=auth.uid() AND g.organization_id=t.organization_id
   AND g.facility_id=t.facility_id AND g.scope=t.authority_class AND g.can_record AND g.revoked_at IS NULL AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp())))
  OR (t.authority_class='resident' AND haven.app_role()::text NOT IN('owner','org_admin','facility_admin','med_tech'))
  OR (p_roles IS NOT NULL AND NOT (haven.app_role()=ANY(p_roles))) THEN
  RAISE EXCEPTION 'Operation unavailable' USING ERRCODE='42501';
 END IF;
END $function$;

CREATE OR REPLACE FUNCTION haven.operation_facility_access(p_facility uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS(SELECT 1 FROM haven.current_authorized_actor() a
 JOIN public.user_facility_access g ON g.user_id=a.actor_user_id AND g.organization_id=a.actor_organization_id
 JOIN public.facilities f ON f.id=g.facility_id AND f.organization_id=a.actor_organization_id
 WHERE a.actor_is_managed AND a.actor_app_role::text IN('housekeeper','owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role')
 AND g.facility_id=p_facility AND g.revoked_at IS NULL
 AND (g.operation_expires_at IS NULL OR g.operation_expires_at>clock_timestamp()) AND f.deleted_at IS NULL)
$function$;

CREATE OR REPLACE FUNCTION haven.operation_issue_actor_classes(i operation_issues)
 RETURNS text[]
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT ARRAY(SELECT c FROM (VALUES
  ('manager',haven.app_role()::text IN('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role')),
  ('owner',(i.owner_user_id IS NOT NULL AND i.owner_user_id=auth.uid()) OR (i.owner_role IS NOT NULL AND i.owner_role=haven.app_role())),
  ('backup',(i.backup_user_id IS NOT NULL AND i.backup_user_id=auth.uid()) OR (i.backup_role IS NOT NULL AND i.backup_role=haven.app_role())),
  ('reporter',i.reported_by=auth.uid())) v(c,ok) WHERE ok)
$function$;

CREATE OR REPLACE FUNCTION haven.operation_issue_role_allowed(p_role app_role)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 SELECT p_role::text IN('housekeeper','owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role')
$function$;

CREATE OR REPLACE FUNCTION haven.operation_reminder_recipient_current(p_user uuid, p_task uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT coalesce(haven.operation_issue_user_current(p_user,t.organization_id,t.facility_id),false)
 AND haven.operation_issue_user_role_allowed(p_user)
 AND (t.authority_class IN('facility','asset') OR EXISTS(SELECT 1 FROM public.operation_subject_access g WHERE g.user_id=p_user AND g.organization_id=t.organization_id AND g.facility_id=t.facility_id AND g.scope=t.authority_class AND g.can_record AND g.revoked_at IS NULL AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp())))
 AND (t.authority_class<>'employee_medical' OR EXISTS(SELECT 1 FROM public.employee_medical_access g WHERE g.user_id=p_user AND g.organization_id=t.organization_id AND g.facility_id=t.facility_id AND g.revoked_at IS NULL))
 AND (t.authority_class<>'financial' OR p.app_role::text IN('owner','org_admin'))
 AND (t.authority_class<>'resident' OR p.app_role::text IN('owner','org_admin','facility_admin','med_tech'))
 AND (t.authority_class<>'employee_personnel' OR p.app_role::text IN('owner','org_admin','facility_admin','manager') OR EXISTS(SELECT 1 FROM public.operation_activity_subjects s JOIN public.staff employee ON employee.id=s.employee_id WHERE s.id=t.subject_id AND employee.user_id=p_user))
 FROM public.operation_task_instances t JOIN public.user_profiles p ON p.id=p_user WHERE t.id=p_task
$function$;

CREATE OR REPLACE FUNCTION haven.operation_task_mutable(p_task uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT haven.operation_task_readable(p_task) AND EXISTS(SELECT 1 FROM public.operation_task_instances t WHERE t.id=p_task
 AND (t.authority_class IN('facility','asset') OR EXISTS(SELECT 1 FROM public.operation_subject_access g
 WHERE g.user_id=auth.uid() AND g.organization_id=t.organization_id AND g.facility_id=t.facility_id AND g.scope=t.authority_class AND g.can_record AND g.revoked_at IS NULL AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp())))
 AND (t.authority_class<>'resident' OR haven.app_role()::text IN('owner','org_admin','facility_admin','med_tech'))
 AND (t.assigned_to=auth.uid() OR (t.assigned_to IS NULL AND t.assigned_role=haven.app_role()::text)
 OR haven.app_role()::text IN('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','dietary', 'cook','maintenance_role')))
$function$;

CREATE OR REPLACE FUNCTION haven.provider_report_context(p_task uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.operation_task_instances;s public.operation_activity_subjects;a public.operation_activities;
BEGIN
 IF haven.authorized_user_id() IS NULL OR NOT coalesce(haven.operation_task_readable(p_task),false) THEN RAISE EXCEPTION 'Provider report scope unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.operation_task_instances WHERE id=p_task;
 SELECT * INTO s FROM public.operation_activity_subjects WHERE id=t.subject_id;
 SELECT * INTO a FROM public.operation_activities WHERE id=t.activity_id;
 RETURN jsonb_build_object('task_id',t.id,'subject_id',t.subject_id,'organization_id',t.organization_id,'facility_id',t.facility_id,'resident_id',s.resident_id,'timezone',coalesce((SELECT timezone FROM public.facilities WHERE id=t.facility_id),'America/New_York'),
 'eligible',a.activity_key='hfo-al-h01-01' AND a.activity_kind='record_review' AND s.subject_kind='resident' AND t.authority_class='resident',
 'can_manage',haven.operation_task_mutable(p_task),
 'native_read',haven.app_role() NOT IN('dietary', 'cook','maintenance_role') AND t.facility_id IN(SELECT haven.accessible_facility_ids()) AND has_table_privilege('authenticated','public.resident_documents','SELECT'),
 'native_write',haven.app_role() IN('owner','org_admin','facility_admin','med_tech') AND t.facility_id IN(SELECT haven.accessible_facility_ids()) AND has_table_privilege('authenticated','public.resident_documents','INSERT'));
END $function$;

CREATE OR REPLACE FUNCTION haven.provider_resident_access(p_org uuid, p_site uuid, p_resident uuid)
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 SELECT coalesce(haven.authorized_user_id() IS NOT NULL AND haven.organization_id()=p_org AND haven.app_role() NOT IN('dietary', 'cook','maintenance_role')
 AND p_site IN(SELECT haven.accessible_facility_ids()) AND has_table_privilege('authenticated','public.resident_documents','SELECT')
 AND EXISTS(SELECT 1 FROM public.residents r WHERE r.id=p_resident AND r.organization_id=p_org AND r.facility_id=p_site AND r.deleted_at IS NULL)
 AND EXISTS(SELECT 1 FROM public.operation_task_instances t JOIN public.operation_activity_subjects s ON s.id=t.subject_id JOIN public.operation_activities a ON a.id=t.activity_id
 WHERE t.organization_id=p_org AND t.facility_id=p_site AND s.resident_id=p_resident AND s.subject_kind='resident' AND t.authority_class='resident' AND a.activity_key='hfo-al-h01-01' AND a.activity_kind='record_review' AND haven.operation_task_readable(t.id)),false)
$function$;

CREATE OR REPLACE FUNCTION haven.referral_capability(p_capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT COALESCE((
    SELECT CASE p_capability
      WHEN 'lead_read' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech'
      ])
      WHEN 'contact_read' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech'
      ])
      WHEN 'clinical_read' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','med_tech'
      ])
      WHEN 'lead_write' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','med_tech'
      ])
      WHEN 'lead_export' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech'
      ])
      WHEN 'duplicate_review' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','med_tech'
      ])
      WHEN 'triage_submit' THEN actor.actor_role_text = ANY (ARRAY[
        'owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech'
      ])
      WHEN 'triage_read' THEN actor.actor_role_text = ANY (ARRAY['owner','org_admin'])
      WHEN 'source_manage' THEN actor.actor_role_text = ANY (ARRAY['owner','org_admin'])
      ELSE false
    END
    FROM haven.current_authorized_actor() AS actor
    WHERE actor.actor_is_managed
    LIMIT 1
  ), false)
$function$;

CREATE OR REPLACE FUNCTION haven.referral_staff_current_for_facility(p_user_id uuid, p_organization_id uuid, p_facility_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_profiles AS profile
    WHERE profile.id = p_user_id
      AND profile.organization_id = p_organization_id
      AND profile.is_active
      AND profile.deleted_at IS NULL
      AND profile.app_role IN ('owner', 'org_admin', 'facility_admin', 'med_tech')
      AND (
        profile.app_role IN ('owner', 'org_admin')
        OR EXISTS (
          SELECT 1
          FROM public.user_facility_access AS access
          JOIN public.facilities AS facility ON facility.id = access.facility_id
          WHERE access.user_id = profile.id
            AND access.organization_id = profile.organization_id
            AND access.facility_id = p_facility_id
            AND access.revoked_at IS NULL
            AND facility.organization_id = profile.organization_id
            AND facility.deleted_at IS NULL
        )
      )
  )
$function$;

CREATE OR REPLACE FUNCTION haven.resident_record_intake_can_read(p_organization_id uuid, p_facility_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT coalesce(haven.organization_id()=p_organization_id
    AND haven.app_role() IN ('owner','org_admin','facility_admin','med_tech')
    AND haven.has_facility_access(p_facility_id),false)
$function$;

CREATE OR REPLACE FUNCTION haven.resident_record_intake_scope(p_intake_id uuid, p_write boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.resident_record_intakes; a record;
BEGIN
  SELECT * INTO a FROM haven.current_authorized_actor() WHERE actor_is_managed LIMIT 1;
  IF a.actor_user_id IS NULL OR a.actor_role_text NOT IN ('owner','org_admin','facility_admin','med_tech') THEN
    RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v FROM public.resident_record_intakes WHERE id=p_intake_id AND deleted_at IS NULL;
  IF NOT FOUND OR v.organization_id IS DISTINCT FROM a.actor_organization_id
     OR NOT haven.has_facility_access(v.facility_id) THEN
    RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501';
  END IF;
  IF v.resident_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.residents r WHERE r.id=v.resident_id
      AND r.organization_id=v.organization_id AND r.facility_id=v.facility_id AND r.deleted_at IS NULL
  ) THEN RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501'; END IF;
  IF v.admission_case_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.admission_cases c WHERE c.id=v.admission_case_id
      AND c.organization_id=v.organization_id AND c.facility_id=v.facility_id
      AND c.resident_id=v.resident_id AND c.deleted_at IS NULL
  ) THEN RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('actor_id',a.actor_user_id,'organization_id',v.organization_id,
    'facility_id',v.facility_id,'role',a.actor_role_text,'resident_id',v.resident_id,
    'admission_case_id',v.admission_case_id,'revision',v.revision,'state',v.state);
END
$function$;

CREATE OR REPLACE FUNCTION haven.resident_record_reviewer_allowed(p_class resident_record_reviewer_class)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT CASE p_class
    WHEN 'clinical' THEN haven.app_role()='med_tech'
    WHEN 'payer' THEN haven.app_role() IN ('owner','org_admin','facility_admin')
    WHEN 'legal' THEN haven.app_role() IN ('owner','org_admin','facility_admin')
    WHEN 'authority' THEN haven.app_role() IN ('owner','org_admin','facility_admin')
    ELSE haven.app_role() IN ('owner','org_admin','facility_admin','med_tech')
  END
$function$;

CREATE OR REPLACE FUNCTION public.acknowledge_care_event(p_care_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text := haven.app_role()::text;
  v_event record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF v_role IS NULL OR v_role NOT IN ('owner','org_admin','facility_admin','admin_assistant','manager','coordinator','med_tech') THEN
    RAISE EXCEPTION 'care_event: forbidden';
  END IF;

  SELECT ce.id, ce.status, ce.facility_id, ce.organization_id, ce.incident_id
    INTO v_event
  FROM public.care_events ce
  WHERE ce.id = p_care_event_id AND ce.deleted_at IS NULL;
  IF v_event.id IS NULL
     OR v_event.organization_id <> haven.organization_id()
     OR v_event.facility_id NOT IN (SELECT haven.accessible_facility_ids()) THEN
    RAISE EXCEPTION 'care_event: forbidden';
  END IF;
  IF v_event.status <> 'open' THEN
    RETURN;
  END IF;

  PERFORM set_config('haven.care_event_definer', '1', true);

  UPDATE public.care_events
  SET status = 'acknowledged', acknowledged_by = v_uid, acknowledged_at = now()
  WHERE id = v_event.id;

  UPDATE public.care_event_deliveries
  SET status = 'acknowledged', acknowledged_at = now()
  WHERE care_event_id = v_event.id
    AND target_user_id = v_uid
    AND status = 'queued';

  UPDATE public.care_event_deliveries
  SET status = 'skipped', skip_reason = 'acknowledged'
  WHERE care_event_id = v_event.id
    AND status = 'queued'
    AND send_after > now();

  IF v_event.incident_id IS NOT NULL THEN
    UPDATE public.incidents
    SET administrator_notified = true,
        administrator_notified_at = COALESCE(administrator_notified_at, now()),
        nurse_notified = CASE WHEN v_role = 'med_tech' THEN true ELSE nurse_notified END,
        nurse_notified_at = CASE WHEN v_role = 'med_tech' THEN COALESCE(nurse_notified_at, now()) ELSE nurse_notified_at END,
        nurse_notified_by = CASE WHEN v_role = 'med_tech' THEN COALESCE(nurse_notified_by, v_uid) ELSE nurse_notified_by END
    WHERE id = v_event.incident_id;
  END IF;

  UPDATE public.exec_alerts
  SET acknowledged_at = now(), acknowledged_by = v_uid
  WHERE organization_id = v_event.organization_id
    AND deep_link_path = '/admin/care-events/' || v_event.id::text
    AND status = 'open'
    AND acknowledged_at IS NULL
    AND deleted_at IS NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.activate_reviewed_diet_order(p_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_order public.diet_orders%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR haven.app_role() NOT IN ('owner','org_admin','facility_admin','med_tech') THEN RAISE EXCEPTION 'Clinical order review role required'; END IF;
  SELECT * INTO v_order FROM public.diet_orders WHERE id=p_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR v_order.status <> 'draft' THEN RAISE EXCEPTION 'Draft order unavailable'; END IF;
  IF v_order.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'Order changed. Review again before activation'; END IF;
  IF v_order.iddsi_food_level IS NULL OR v_order.iddsi_liquid_level IS NULL THEN RAISE EXCEPTION 'Review and record both IDDSI levels before activation'; END IF;
  PERFORM 1 FROM public.residents WHERE id=v_order.resident_id FOR UPDATE;
  UPDATE public.diet_orders SET status='superseded',active=false,effective_to=now(),updated_by=auth.uid() WHERE resident_id=v_order.resident_id AND id<>p_id AND active;
  UPDATE public.diet_orders SET status='active',active=true,ordered_by=auth.uid(),updated_by=auth.uid(),effective_from=now() WHERE id=p_id;
  RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.allocate_incident_number(p_facility_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'haven'
AS $function$
DECLARE
  v_year integer;
  v_prefix text;
  v_next integer;
  v_org uuid;
  v_clean text;
  v_existing_max integer;
BEGIN
  IF auth.uid () IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT (haven.app_role () = ANY (ARRAY['owner'::app_role, 'org_admin'::app_role, 'facility_admin'::app_role, 'manager'::app_role, 'admin_assistant'::app_role, 'coordinator'::app_role, 'med_tech'::app_role, 'caregiver'::app_role, 'med_tech'::app_role])) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT
    f.organization_id INTO v_org
  FROM
    facilities f
  WHERE
    f.id = p_facility_id
    AND f.deleted_at IS NULL;

  IF v_org IS NULL OR v_org <> haven.organization_id () THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF p_facility_id NOT IN (
    SELECT
      haven.accessible_facility_ids ()) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_year := (EXTRACT(YEAR FROM timezone('America/New_York', now())))::integer;

  SELECT
    COALESCE(NULLIF(trim(f.settings ->> 'incident_report_prefix'), ''), '') INTO v_prefix
  FROM
    facilities f
  WHERE
    f.id = p_facility_id;

  IF v_prefix IS NULL OR length(v_prefix) = 0 THEN
    SELECT
      regexp_replace(f.name, '[^a-zA-Z]', '', 'g') INTO v_clean
    FROM
      facilities f
    WHERE
      f.id = p_facility_id;
    v_prefix := upper(left(coalesce(v_clean, ''), 3));
  END IF;

  IF v_prefix IS NULL OR length(v_prefix) < 3 THEN
    v_prefix := 'HVN';
  END IF;

  IF length(v_prefix) > 12 THEN
    v_prefix := left(v_prefix, 12);
  END IF;

  SELECT
    COALESCE(MAX(COALESCE(NULLIF(substring(i.incident_number FROM '([0-9]+)$'), ''), '0')::integer), 0) INTO v_existing_max
  FROM
    incidents i
  WHERE
    i.facility_id = p_facility_id
    AND i.deleted_at IS NULL
    AND i.incident_number LIKE format('%s-%s-%%', v_prefix, v_year);

  INSERT INTO incident_sequences (facility_id, year, last_number)
    VALUES (p_facility_id, v_year, v_existing_max)
  ON CONFLICT (facility_id, year)
    DO NOTHING;

  UPDATE
    incident_sequences
  SET
    last_number = GREATEST(last_number + 1, v_existing_max + 1)
  WHERE
    facility_id = p_facility_id
    AND year = v_year
  RETURNING
    last_number INTO v_next;

  RETURN format('%s-%s-%s', v_prefix, v_year, lpad(v_next::text, 4, '0'));
END
$function$;

CREATE OR REPLACE FUNCTION public.apply_col_discovery_round_observation_plan(p_resident_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'haven'
AS $function$
DECLARE
  v_org_id uuid;
  v_entity_id uuid;
  v_facility_id uuid;
  v_facility_name text;
  v_plan_id uuid;
  v_existing_plan_id uuid;
  v_profile text;
  v_rule jsonb;
  v_sort_order integer := 0;
  v_is_service_role boolean;
BEGIN
  v_is_service_role := COALESCE(auth.role() = 'service_role', false);

  SELECT
    res.organization_id,
    fac.entity_id,
    res.facility_id,
    fac.name
  INTO v_org_id, v_entity_id, v_facility_id, v_facility_name
  FROM public.residents res
  JOIN public.facilities fac ON fac.id = res.facility_id AND fac.deleted_at IS NULL
  WHERE res.id = p_resident_id
    AND res.deleted_at IS NULL
    AND fac.organization_id = '00000000-0000-0000-0000-000000000001';

  IF v_facility_id IS NULL THEN
    RAISE EXCEPTION 'Resident % is not assigned to an active COL facility', p_resident_id
      USING ERRCODE = '22023';
  END IF;

  IF NOT v_is_service_role AND auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF NOT v_is_service_role AND haven.app_role() NOT IN ('owner', 'org_admin', 'facility_admin', 'med_tech') THEN
    RAISE EXCEPTION 'Insufficient role' USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_service_role AND NOT haven.has_facility_access(v_facility_id) THEN
    RAISE EXCEPTION 'Facility access denied' USING ERRCODE = '42501';
  END IF;

  IF v_facility_name = 'Plantation ALF' THEN
    RAISE EXCEPTION
      'Plantation ALF discovery round cadence is pending owner decision. Do not apply invented defaults.'
      USING ERRCODE = '22023';
  END IF;

  v_profile := CASE
    WHEN v_facility_name = 'Homewood Lodge ALF' THEN 'homewood_two_hour_night'
    WHEN v_facility_name IN ('Oakridge ALF', 'Rising Oaks ALF', 'Grande Cypress ALF') THEN 'standard_day_night'
    ELSE NULL
  END;

  IF v_profile IS NULL THEN
    RAISE EXCEPTION 'Facility % is not configured for COL discovery round cadence', v_facility_name
      USING ERRCODE = '22023';
  END IF;

  SELECT id
    INTO v_existing_plan_id
  FROM public.resident_observation_plans
  WHERE resident_id = p_resident_id
    AND facility_id = v_facility_id
    AND status = 'active'::public.resident_observation_plan_status
    AND source_type = 'policy'::public.resident_observation_source_type
    AND rationale = 'COL discovery rounds default (owner 2026-08-14)'
    AND deleted_at IS NULL
  ORDER BY effective_from DESC
  LIMIT 1;

  IF v_existing_plan_id IS NOT NULL THEN
    RETURN v_existing_plan_id;
  END IF;

  INSERT INTO public.resident_observation_plans (
    organization_id,
    entity_id,
    facility_id,
    resident_id,
    status,
    source_type,
    effective_from,
    rationale,
    created_by
  ) VALUES (
    v_org_id,
    v_entity_id,
    v_facility_id,
    p_resident_id,
    'active'::public.resident_observation_plan_status,
    'policy'::public.resident_observation_source_type,
    now(),
    'COL discovery rounds default (owner 2026-08-14)',
    auth.uid()
  )
  RETURNING id INTO v_plan_id;

  FOR v_rule IN
    SELECT value
    FROM jsonb_array_elements(
      CASE
        WHEN v_profile = 'homewood_two_hour_night' THEN haven._col_discovery_homewood_preset_rules()
        ELSE haven._col_discovery_standard_preset_rules()
      END
    )
  LOOP
  INSERT INTO public.resident_observation_plan_rules (
    plan_id,
    organization_id,
    entity_id,
    facility_id,
    resident_id,
    interval_type,
    interval_minutes,
    shift,
    daypart_start,
    daypart_end,
    days_of_week,
    grace_minutes,
    required_fields_schema,
    escalation_policy_key,
    sort_order,
    active
  ) VALUES (
    v_plan_id,
    v_org_id,
    v_entity_id,
    v_facility_id,
    p_resident_id,
    (v_rule ->> 'interval_type')::public.resident_observation_interval_type,
    NULLIF(v_rule ->> 'interval_minutes', '')::integer,
    NULLIF(v_rule ->> 'shift', '')::public.shift_type,
    NULLIF(v_rule ->> 'daypart_start', '')::time,
    NULLIF(v_rule ->> 'daypart_end', '')::time,
    ARRAY(SELECT jsonb_array_elements_text(v_rule -> 'days_of_week')::integer),
    COALESCE((v_rule ->> 'grace_minutes')::integer, 30),
    COALESCE(v_rule -> 'required_fields_schema', '{}'::jsonb),
    COALESCE(v_rule ->> 'escalation_policy_key', 'resident-assurance-standard'),
    COALESCE((v_rule ->> 'sort_order')::integer, v_sort_order),
    COALESCE((v_rule ->> 'active')::boolean, true)
  );

    v_sort_order := v_sort_order + 1;
  END LOOP;

  RETURN v_plan_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.attach_care_event_file(p_care_event_id uuid, p_path text, p_kind text DEFAULT 'photo'::text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text := haven.app_role()::text;
  v_event record;
  v_path text := NULLIF(btrim(COALESCE(p_path, '')), '');
  v_kind text := COALESCE(NULLIF(btrim(COALESCE(p_kind, '')), ''), 'photo');
  v_attachments jsonb;
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF v_kind NOT IN ('photo','scanned_form','physician_order','other') THEN
    RAISE EXCEPTION 'care_event: unknown attachment kind';
  END IF;
  IF v_path IS NULL THEN
    RAISE EXCEPTION 'care_event: a file path is required';
  END IF;

  SELECT ce.id, ce.organization_id, ce.facility_id, ce.reported_by, ce.incident_id, ce.answers
    INTO v_event
  FROM public.care_events ce
  WHERE ce.id = p_care_event_id AND ce.deleted_at IS NULL;
  IF v_event.id IS NULL
     OR v_event.organization_id <> haven.organization_id()
     OR v_event.facility_id NOT IN (SELECT haven.accessible_facility_ids()) THEN
    RAISE EXCEPTION 'care_event: forbidden';
  END IF;
  IF v_event.reported_by <> v_uid
     AND (v_role IS NULL OR v_role NOT IN ('owner','org_admin','facility_admin','admin_assistant','manager','med_tech')) THEN
    RAISE EXCEPTION 'care_event: forbidden';
  END IF;

  -- Path law, same as append_care_event_note: the storage policies scope on the
  -- first two segments, so a path shaped any other way is refused here rather
  -- than landing somewhere the policies do not cover.
  IF v_path !~ ('^' || v_event.organization_id::text || '/' || v_event.facility_id::text || '/' || v_event.id::text || '/[^/]+$') THEN
    RAISE EXCEPTION 'care_event: file path must be <organization_id>/<facility_id>/<care_event_id>/<file>';
  END IF;

  PERFORM set_config('haven.care_event_definer', '1', true);

  v_attachments := CASE WHEN jsonb_typeof(v_event.answers -> 'attachments') = 'array'
                        THEN v_event.answers -> 'attachments' ELSE '[]'::jsonb END;
  v_count := jsonb_array_length(v_attachments);
  IF v_count >= 10 THEN
    RAISE EXCEPTION 'care_event: ten files is the limit for one incident';
  END IF;
  IF v_attachments @> to_jsonb(v_path) THEN
    RAISE EXCEPTION 'care_event: that file is already attached';
  END IF;

  v_attachments := v_attachments || to_jsonb(v_path);
  UPDATE public.care_events
  SET answers = answers || jsonb_build_object('attachments', v_attachments)
  WHERE id = v_event.id;

  -- Always a row, incident or not. Without one the object is in the bucket and
  -- on no surface, which is the same as losing it.
  INSERT INTO public.incident_photos (
    incident_id, care_event_id, facility_id, organization_id, storage_path, description, kind, taken_by
  ) VALUES (
    v_event.incident_id, v_event.id, v_event.facility_id, v_event.organization_id, v_path,
    NULLIF(btrim(COALESCE(p_description, '')), ''), v_kind, v_uid
  );

  RETURN jsonb_build_object(
    'care_event_id', v_event.id,
    'path', v_path,
    'kind', v_kind,
    'count', jsonb_array_length(v_attachments)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.care_event_print_record(p_print_kind text, p_care_event_id uuid DEFAULT NULL::uuid, p_facility_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text := haven.app_role()::text;
  v_org uuid := haven.organization_id();
  v_facility uuid := p_facility_id;
  v_record uuid;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF p_print_kind NOT IN ('incident_form','physician_sheet','incident_reports_log','taxonomy_packet') THEN
    RAISE EXCEPTION 'print: unknown print kind';
  END IF;

  -- The physician sheet and the incident form carry a resident's clinical
  -- detail; the log and the packet are facility-wide. Neither is for the floor.
  IF p_print_kind IN ('incident_form','physician_sheet','incident_reports_log') THEN
    IF v_role IS NULL OR v_role NOT IN ('owner','org_admin','facility_admin','admin_assistant','manager','med_tech') THEN
      RAISE EXCEPTION 'print: forbidden';
    END IF;
  ELSE
    IF v_role IS NULL OR v_role NOT IN ('owner','org_admin') THEN
      RAISE EXCEPTION 'print: forbidden';
    END IF;
  END IF;

  IF p_care_event_id IS NOT NULL THEN
    SELECT ce.facility_id INTO v_facility
    FROM public.care_events ce
    WHERE ce.id = p_care_event_id AND ce.deleted_at IS NULL AND ce.organization_id = v_org;
    IF v_facility IS NULL THEN
      RAISE EXCEPTION 'print: forbidden';
    END IF;
    v_record := p_care_event_id;
  ELSE
    v_record := v_facility;
  END IF;

  IF v_facility IS NULL OR v_facility NOT IN (SELECT haven.accessible_facility_ids()) THEN
    RAISE EXCEPTION 'print: forbidden';
  END IF;

  INSERT INTO public.audit_log (
    table_name, record_id, action, new_data, user_id, organization_id, facility_id
  ) VALUES (
    'care_event_print', v_record, 'INSERT',
    jsonb_build_object(
      'event', 'care_event_printed',
      'print_kind', p_print_kind,
      'care_event_id', p_care_event_id,
      'range_from', p_from,
      'range_to', p_to
    ),
    v_uid, v_org, v_facility
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.claim_observation_escalation_deliveries(p_organization_id uuid, p_facility_id uuid, p_claim_token uuid, p_at timestamp with time zone, p_limit integer)
 RETURNS TABLE(id uuid, organization_id uuid, facility_id uuid, dispatch_id uuid, rung_key text, target_user_id uuid, target_phone text, channel text, is_test boolean, message_body text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  -- Two data modifying branches in one statement. They target disjoint rows,
  -- because one requires the attempt cap to be exhausted and the other requires
  -- it not to be, so neither can see or fight the other.
  WITH unavailable AS (
    UPDATE public.observation_escalation_deliveries d SET status='skipped',skip_reason='in_app_surface_unavailable',claim_token=NULL,updated_at=now()
    WHERE d.organization_id=p_organization_id AND (p_facility_id IS NULL OR d.facility_id=p_facility_id)
      AND (d.status='queued' OR (d.status='sending' AND d.claimed_at < p_at - haven.observation_delivery_claim_timeout() AND d.send_attempts < haven.observation_delivery_max_attempts())) AND d.channel='in_app' AND d.send_after <= p_at
      AND NOT (EXISTS (SELECT 1 FROM public.user_profiles up
 JOIN public.observation_escalation_dispatches dispatch ON dispatch.id=d.dispatch_id AND dispatch.escalation_id IS NOT NULL
 WHERE up.id=d.target_user_id AND up.organization_id=d.organization_id
 AND up.is_active AND up.deleted_at IS NULL
 AND (up.app_role IN ('owner','org_admin') OR (up.app_role IN ('facility_admin','manager','med_tech')
 AND EXISTS(SELECT 1 FROM public.user_facility_access ufa WHERE ufa.user_id=up.id AND ufa.facility_id=d.facility_id AND ufa.organization_id=d.organization_id AND ufa.revoked_at IS NULL))))) RETURNING d.id
  ), exhausted AS (
    -- A claim nobody came back for, on a delivery that has already had its
    -- chances. Failed rather than handed out again: this is the branch that
    -- turns an unbounded resend into a terminal state somebody can see.
    UPDATE
      public.observation_escalation_deliveries d
    SET
      status = 'failed',
      error_message = 'Abandoned mid send and out of attempts',
      claim_token = NULL,
      updated_at = now()
    WHERE
      d.organization_id = p_organization_id
      AND (p_facility_id IS NULL
        OR d.facility_id = p_facility_id)
      AND d.status = 'sending'
      AND d.claimed_at < p_at - haven.observation_delivery_claim_timeout ()
      AND d.send_attempts >= haven.observation_delivery_max_attempts ()
    RETURNING
      d.id
),
claimed AS (
  UPDATE
    public.observation_escalation_deliveries d
  SET
    status = 'sending',
    claimed_at = p_at,
    claim_token = p_claim_token,
    send_attempts = d.send_attempts + 1,
    updated_at = now()
  WHERE
    d.id IN (
      SELECT
        candidate.id
      FROM
        public.observation_escalation_deliveries candidate
      WHERE
        candidate.organization_id = p_organization_id
        AND (p_facility_id IS NULL
          OR candidate.facility_id = p_facility_id)
        AND (candidate.channel <> 'in_app' OR (EXISTS (SELECT 1 FROM public.user_profiles up
 JOIN public.observation_escalation_dispatches dispatch ON dispatch.id=candidate.dispatch_id AND dispatch.escalation_id IS NOT NULL
 WHERE up.id=candidate.target_user_id AND up.organization_id=candidate.organization_id
 AND up.is_active AND up.deleted_at IS NULL
 AND (up.app_role IN ('owner','org_admin') OR (up.app_role IN ('facility_admin','manager','med_tech')
 AND EXISTS(SELECT 1 FROM public.user_facility_access ufa WHERE ufa.user_id=up.id AND ufa.facility_id=candidate.facility_id AND ufa.organization_id=candidate.organization_id AND ufa.revoked_at IS NULL))))))
        AND candidate.send_after <= p_at
        AND candidate.send_attempts < haven.observation_delivery_max_attempts ()
        AND (candidate.status = 'queued'
          -- A claim its owner never finished. The tick that took it is gone.
          OR (candidate.status = 'sending'
            AND candidate.claimed_at < p_at - haven.observation_delivery_claim_timeout ()))
      ORDER BY
        candidate.send_after
      LIMIT LEAST(GREATEST(COALESCE(p_limit, 1), 1), 500)
      FOR UPDATE
        SKIP LOCKED)
  RETURNING
    d.id,
    d.organization_id,
    d.facility_id,
    d.dispatch_id,
    d.rung_key,
    d.target_user_id,
    d.target_phone,
    d.channel,
    d.is_test,
    d.message_body
)
  SELECT
    *
  FROM
    claimed;
$function$;

CREATE OR REPLACE FUNCTION public.claim_observation_task(p_task_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE t public.resident_observation_tasks%ROWTYPE; actor jsonb; aid uuid:=auth.uid(); sid uuid; claim_version integer; role_name text; assignment uuid; observer_staff_id uuid;
BEGIN
 SELECT * INTO t FROM public.resident_observation_tasks WHERE id=p_task_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Observation task not found' USING ERRCODE='P0002'; END IF;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;
 SELECT p.app_role::text INTO role_name FROM public.user_profiles p WHERE p.id=aid;
 claim_version:=nullif(auth.jwt()->>'auth_claim_version','')::integer;
 IF aid IS NULL OR sid IS NULL OR role_name NOT IN('caregiver','med_tech','med_tech','manager','coordinator','admin_assistant','facility_admin','org_admin','owner') THEN
  RAISE EXCEPTION 'An authorized observer is required to take this check' USING ERRCODE='42501'; END IF;
 actor:=haven.assert_rounding_service_actor(aid,role_name,sid,claim_version,t.organization_id,t.facility_id,false,true);
 observer_staff_id:=(actor->>'staff_id')::uuid;
 IF t.status NOT IN('upcoming','due_soon','due_now','overdue','critically_overdue','reassigned','escalated') THEN
  RAISE EXCEPTION 'This check is no longer available to take' USING ERRCODE='22023'; END IF;
 INSERT INTO public.resident_observation_assignments(organization_id,entity_id,facility_id,resident_id,task_id,staff_id,assignment_type,reason,created_by)
 VALUES(t.organization_id,t.entity_id,t.facility_id,t.resident_id,t.id,observer_staff_id,'rescue','Observer explicitly took responsibility for this check',aid)
 ON CONFLICT(task_id,staff_id) WHERE released_at IS NULL DO NOTHING RETURNING id INTO assignment;
 IF assignment IS NULL THEN SELECT a.id INTO assignment FROM public.resident_observation_assignments a WHERE a.task_id=t.id AND a.staff_id=observer_staff_id AND a.released_at IS NULL; END IF;
 RETURN jsonb_build_object('task_id',t.id,'staff_id',observer_staff_id,'assignment_id',assignment,'claimed',true);
END $function$;

CREATE OR REPLACE FUNCTION public.close_outbreak_review(p_id uuid, p_status text, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE outbreak infection_outbreaks%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR coalesce(haven.app_role()::text,'') NOT IN('owner','org_admin','facility_admin','med_tech') OR coalesce(p_status,'') NOT IN('contained','resolved') OR nullif(trim(p_notes),'') IS NULL THEN RAISE EXCEPTION 'Clinical review and evidence are required'; END IF;
 SELECT * INTO STRICT outbreak FROM infection_outbreaks WHERE id=p_id AND deleted_at IS NULL FOR UPDATE;
 IF p_status='resolved' AND (EXISTS(SELECT 1 FROM infection_surveillance WHERE outbreak_id=p_id AND status IN('suspected','confirmed') AND deleted_at IS NULL) OR EXISTS(SELECT 1 FROM outbreak_actions WHERE outbreak_id=p_id AND status IN('pending','in_progress') AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'Resolve active cases and complete the outbreak action checklist before closing'; END IF;
 UPDATE infection_outbreaks SET status=p_status,contained_at=CASE WHEN p_status='contained' THEN now() ELSE contained_at END,resolved_at=CASE WHEN p_status='resolved' THEN now() ELSE resolved_at END,resolved_by=CASE WHEN p_status='resolved' THEN auth.uid() ELSE resolved_by END,notes=concat_ws(E'\n',notes,p_notes),updated_by=auth.uid() WHERE id=p_id;
 RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.complete_rounding_task_review(p_task_id uuid, p_actor_id uuid, p_actor_role text, p_session_id uuid, p_claim_version integer, p_organization_id uuid, p_facility_id uuid, p_actual_staff_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_request uuid:=(p_payload->>'request_id')::uuid;
 v_task public.resident_observation_tasks%ROWTYPE;
 v_receipt public.rounding_completion_receipts%ROWTYPE;
 v_actor jsonb; v_staff uuid; v_role text; v_has_assignment boolean; v_is_assignee boolean;
 v_payload jsonb; v_result jsonb; v_log uuid; v_observed timestamptz; v_entered timestamptz;
 v_mode text; v_status text; v_exception text; v_delay integer; v_severity text; v_flag text;
 v_late boolean:=false; v_pattern boolean:=false; v_minute integer; v_recent integer; v_residents integer;
BEGIN
 IF v_request IS NULL OR p_payload->>'observed_at' IS NULL THEN
  RAISE EXCEPTION 'A request identity and observation time are required' USING ERRCODE='22023';
 END IF;
 -- Same key is serialized even across distinct tasks/actors, then task and
 -- staff/facility locks serialize completion and pattern threshold detection.
 PERFORM pg_advisory_xact_lock(hashtextextended('rounding-request:'||v_request::text,0));
 SELECT * INTO v_task FROM public.resident_observation_tasks
 WHERE id=p_task_id AND organization_id=p_organization_id AND facility_id=p_facility_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Observation task not found' USING ERRCODE='P0002'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rounding-pattern:'||p_facility_id::text||':'||p_actual_staff_id::text,0));
 v_actor:=haven.assert_rounding_service_actor(p_actor_id,p_actor_role,p_session_id,p_claim_version,p_organization_id,p_facility_id,false,true);
 v_staff:=(v_actor->>'staff_id')::uuid; v_role:=v_actor->>'role';
 IF v_staff IS DISTINCT FROM p_actual_staff_id THEN RAISE EXCEPTION 'Rounding actor staff identity changed' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.resident_observation_assignments a
 WHERE a.task_id=v_task.id AND a.organization_id=p_organization_id AND a.facility_id=p_facility_id AND a.released_at IS NULL
 ORDER BY a.id FOR SHARE;
 SELECT EXISTS(SELECT 1 FROM public.resident_observation_assignments a WHERE a.task_id=v_task.id AND a.organization_id=p_organization_id AND a.facility_id=p_facility_id AND a.released_at IS NULL),
 EXISTS(SELECT 1 FROM public.resident_observation_assignments a WHERE a.task_id=v_task.id AND a.organization_id=p_organization_id AND a.facility_id=p_facility_id AND a.released_at IS NULL AND a.staff_id=v_staff)
 INTO v_has_assignment,v_is_assignee;
 -- Assignee guard, unchanged from the approved 331 body. A task with no assigned
 -- staff stays uncompletable by a floor role: supabase/tests/review_authoritative_actor.sql
 -- asserts exactly that, and a tested authorization invariant outranks the
 -- spec's facility pool wording. See the build notes, decision D12.
 IF v_role NOT IN('owner','org_admin','facility_admin','med_tech')
 AND (CASE WHEN v_has_assignment THEN v_is_assignee ELSE v_task.assigned_staff_id=v_staff END) IS NOT TRUE THEN
  RAISE EXCEPTION 'Rounding task assignee changed' USING ERRCODE='42501';
 END IF;
 v_observed:=(p_payload->>'observed_at')::timestamptz;
 IF NOT isfinite(v_observed) THEN RAISE EXCEPTION 'Invalid observation time' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(coalesce(p_payload->'intervention_codes','[]'))<>'array'
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_payload->'intervention_codes','[]')) code WHERE jsonb_typeof(code)<>'string') THEN
  RAISE EXCEPTION 'Invalid intervention codes' USING ERRCODE='22023';
 END IF;
 v_exception:=coalesce(nullif(p_payload->>'exception_type',''),CASE
  WHEN p_payload->>'quick_status'='not_found' THEN 'resident_not_found'
  WHEN p_payload->>'quick_status'='refused' THEN 'resident_declined_interaction'
  WHEN coalesce((p_payload->>'fall_hazard_observed')::boolean,false) THEN 'environmental_hazard_present' END);
 v_payload:=jsonb_build_object(
  'observed_at',v_observed,'quick_status',p_payload->>'quick_status',
  'resident_location',p_payload->>'resident_location','resident_position',p_payload->>'resident_position','resident_state',p_payload->>'resident_state',
  'distress_present',coalesce((p_payload->>'distress_present')::boolean,false),'breathing_concern',coalesce((p_payload->>'breathing_concern')::boolean,false),
  'pain_concern',coalesce((p_payload->>'pain_concern')::boolean,false),'toileting_assisted',coalesce((p_payload->>'toileting_assisted')::boolean,false),
  'hydration_offered',coalesce((p_payload->>'hydration_offered')::boolean,false),'repositioned',coalesce((p_payload->>'repositioned')::boolean,false),
  'skin_concern_observed',coalesce((p_payload->>'skin_concern_observed')::boolean,false),'fall_hazard_observed',coalesce((p_payload->>'fall_hazard_observed')::boolean,false),
  'refused_assistance',coalesce((p_payload->>'refused_assistance')::boolean,false),
  'intervention_codes',coalesce((SELECT jsonb_agg(code ORDER BY code) FROM jsonb_array_elements_text(coalesce(p_payload->'intervention_codes','[]')) code),'[]'),
  'note',p_payload->>'note','late_reason',p_payload->>'late_reason','exception_type',v_exception,
  'chip_selections',coalesce(p_payload->'chip_selections','{}'::jsonb),
  'composed_summary',nullif(btrim(p_payload->>'composed_summary'),''),
  'exception_severity',coalesce(nullif(p_payload->>'exception_severity',''),'medium'),'exception_present',v_exception IS NOT NULL);
 SELECT * INTO v_receipt FROM public.rounding_completion_receipts WHERE id=v_request;
 IF FOUND THEN
  IF v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.task_id IS DISTINCT FROM p_task_id
    OR v_receipt.organization_id IS DISTINCT FROM p_organization_id OR v_receipt.facility_id IS DISTINCT FROM p_facility_id
    OR v_receipt.staff_id IS DISTINCT FROM v_staff OR v_receipt.payload IS DISTINCT FROM v_payload THEN
   RAISE EXCEPTION 'Completion request conflicts with an existing observation' USING ERRCODE='23505';
  END IF;
  RETURN v_receipt.result||jsonb_build_object('replayed',true);
 END IF;
 IF v_task.status IN('completed_on_time','completed_late','excused') OR v_task.completed_log_id IS NOT NULL THEN
  RAISE EXCEPTION 'Observation task is no longer completable' USING ERRCODE='P0001';
 END IF;
 v_entered:=clock_timestamp();
 IF v_observed>v_entered THEN RAISE EXCEPTION 'Observation time cannot be in the future' USING ERRCODE='22023'; END IF;
 v_mode:=CASE WHEN coalesce((p_payload->>'offline')::boolean,false) THEN 'offline_synced'
  WHEN v_observed<v_entered-interval '5 minutes' THEN 'late' ELSE 'live' END;
 IF v_mode='late' AND nullif(haven.rounding_trim_text(v_payload->>'late_reason'),'') IS NULL THEN
  RAISE EXCEPTION 'lateReason is required for late entries' USING ERRCODE='22023';
 END IF;
 v_status:=CASE WHEN v_observed<=v_task.grace_ends_at THEN 'completed_on_time' ELSE 'completed_late' END;
 v_result:=haven.complete_rounding_task_core(p_task_id,p_actor_id,p_actor_role,p_session_id,p_claim_version,p_organization_id,p_facility_id,v_staff,
  v_payload||jsonb_build_object('entered_at',v_entered,'entry_mode',v_mode,'completion_status',v_status));
 v_log:=(v_result->>'log_id')::uuid;
 IF v_mode='late' THEN
  v_delay:=greatest(1,round(extract(epoch FROM (v_entered-v_observed))/60)::integer);
  v_severity:=CASE WHEN v_delay>=240 THEN 'critical' WHEN v_delay>=60 THEN 'high' ELSE 'medium' END;
  IF v_exception IS NOT NULL AND v_severity='medium' THEN v_severity:='high'; END IF;
  IF v_exception IS NOT NULL AND v_severity='high' AND v_delay>=120 THEN v_severity:='critical'; END IF;
  v_flag:=CASE WHEN v_exception IS NOT NULL THEN 'late_entry_with_exception' WHEN v_delay>=240 THEN 'late_entry_over_4h' WHEN v_delay>=60 THEN 'late_entry_over_60m' ELSE 'late_entry_review' END;
  INSERT INTO public.resident_observation_integrity_flags(organization_id,entity_id,facility_id,resident_id,log_id,staff_id,flag_type,severity,status,disposition_note,updated_by)
  VALUES(v_task.organization_id,v_task.entity_id,v_task.facility_id,v_task.resident_id,v_log,v_staff,v_flag,v_severity::public.resident_observation_severity,'open',
   format('Auto-created from a late observation entry (%s min after observation). Reason: %s',v_delay,btrim(v_payload->>'late_reason')),p_actor_id);
  v_late:=true;
 END IF;
 SELECT count(*) FILTER(WHERE entered_at>=date_trunc('minute',v_entered)),count(*) INTO v_minute,v_recent
 FROM public.resident_observation_logs WHERE organization_id=p_organization_id AND facility_id=p_facility_id AND staff_id=v_staff AND deleted_at IS NULL
 AND entered_at>=v_entered-interval '5 minutes' AND entered_at<=v_entered;
 IF v_minute>=3 OR v_recent>=8 THEN
  v_flag:=CASE WHEN v_recent>=8 THEN 'high_velocity_documentation' ELSE 'same_minute_batch_entry' END;
  v_severity:=CASE WHEN v_minute>=6 OR v_recent>=12 THEN 'critical' ELSE 'high' END;
  INSERT INTO public.resident_observation_integrity_flags(organization_id,entity_id,facility_id,resident_id,log_id,staff_id,flag_type,severity,status,disposition_note,updated_by)
  VALUES(v_task.organization_id,v_task.entity_id,v_task.facility_id,v_task.resident_id,v_log,v_staff,v_flag,v_severity::public.resident_observation_severity,'open',
   format('Auto-created from a suspicious documentation pattern: %s entries in the same minute and %s entries in the last 5 minutes.',v_minute,v_recent),p_actor_id);
  v_pattern:=true;
 END IF;
 SELECT count(DISTINCT log.resident_id) INTO v_residents FROM public.resident_observation_logs log
 WHERE log.organization_id=p_organization_id AND log.facility_id=p_facility_id AND log.staff_id=v_staff AND log.deleted_at IS NULL
 AND log.entered_at>=v_entered-interval '15 minutes' AND log.entered_at<=v_entered
 AND haven.rounding_pattern_signature(to_jsonb(log))=haven.rounding_pattern_signature(v_payload);
 IF v_residents>=3 THEN
  INSERT INTO public.resident_observation_integrity_flags(organization_id,entity_id,facility_id,resident_id,log_id,staff_id,flag_type,severity,status,disposition_note,updated_by)
  VALUES(v_task.organization_id,v_task.entity_id,v_task.facility_id,v_task.resident_id,v_log,v_staff,'identical_payload_multi_resident',
   (CASE WHEN v_residents>=5 THEN 'critical' ELSE 'high' END)::public.resident_observation_severity,'open',
   format('Auto-created from repeated identical payload signatures across %s residents within 15 minutes.',v_residents),p_actor_id);
  v_pattern:=true;
 END IF;
 v_result:=v_result||jsonb_build_object('integrityFlagCreated',v_late,'suspiciousPatternFlagCreated',v_pattern,'replayed',false);
 INSERT INTO public.rounding_completion_receipts(id,organization_id,facility_id,actor_id,staff_id,task_id,payload,result)
 VALUES(v_request,p_organization_id,p_facility_id,p_actor_id,v_staff,p_task_id,v_payload,v_result);
 RETURN v_result;
END $function$;

CREATE OR REPLACE FUNCTION public.complete_verified_controlled_counts(p_count_ids uuid[], p_outgoing_id uuid, p_incoming_id uuid, p_facility_id uuid, p_organization_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c public.controlled_substance_counts; matched integer := 0;
BEGIN
  IF p_incoming_id = p_outgoing_id OR cardinality(p_count_ids) IS NULL OR cardinality(p_count_ids) = 0 THEN
    RAISE EXCEPTION 'Two different staff and at least one count are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id=p_outgoing_id AND organization_id=p_organization_id
      AND app_role IN ('med_tech','caregiver','med_tech') AND is_active AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Invalid outgoing count role';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = p_incoming_id AND organization_id = p_organization_id
      AND app_role IN ('med_tech', 'caregiver') AND is_active AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Invalid witness';
  END IF;
  IF (SELECT count(*) FROM public.user_profiles u WHERE u.id IN (p_outgoing_id,p_incoming_id)
      AND u.organization_id=p_organization_id AND u.is_active AND u.deleted_at IS NULL
      AND EXISTS (SELECT 1 FROM public.facilities f WHERE f.id=p_facility_id AND f.organization_id=p_organization_id AND f.deleted_at IS NULL
        AND (u.app_role IN ('owner','org_admin') OR EXISTS (SELECT 1 FROM public.user_facility_access a WHERE a.user_id=u.id
          AND a.facility_id=f.id AND a.organization_id=p_organization_id AND a.revoked_at IS NULL)))) <> 2 THEN
    RAISE EXCEPTION 'Both staff must have active facility access';
  END IF;
  FOR c IN SELECT * FROM public.controlled_substance_counts WHERE id = ANY(p_count_ids) ORDER BY id FOR UPDATE LOOP
    IF c.organization_id <> p_organization_id OR c.facility_id <> p_facility_id OR c.outgoing_staff_id <> p_outgoing_id
       OR c.incoming_staff_id IS NOT NULL OR c.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Count is no longer available for signing'; END IF;
    matched := matched + 1;
  END LOOP;
  IF matched <> cardinality(p_count_ids) THEN RAISE EXCEPTION 'Count list must contain unique existing counts'; END IF;
  UPDATE public.controlled_substance_counts SET incoming_staff_id = p_incoming_id, incoming_signed_at = now() WHERE id = ANY(p_count_ids);
  INSERT INTO public.audit_log(table_name, record_id, action, new_data, user_id, organization_id, facility_id)
    SELECT 'controlled_substance_counts', id, 'UPDATE', jsonb_build_object('event','incoming_co_sign_verified',
      'incoming_staff_id',p_incoming_id,'outgoing_staff_id',p_outgoing_id), p_incoming_id, p_organization_id, p_facility_id
    FROM public.controlled_substance_counts WHERE id = ANY(p_count_ids);
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_care_plan_revision_review(p_id uuid, p_resident_id uuid, p_previous_id uuid, p_effective date, p_review date, p_notes text, p_items jsonb, p_source_form_1823_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r residents%ROWTYPE; previous care_plans%ROWTYPE; item jsonb; position integer:=0; request_hash text;
BEGIN
 IF auth.uid() IS NULL OR haven.app_role() NOT IN('owner','org_admin','facility_admin','med_tech') THEN RAISE EXCEPTION 'Clinical plan author role required'; END IF;
 IF p_effective IS NULL OR p_review<p_effective OR p_review IS NULL OR p_items IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)<1 THEN RAISE EXCEPTION 'Effective date, review date and care needs are required'; END IF;
 SELECT * INTO STRICT r FROM residents WHERE id=p_resident_id AND deleted_at IS NULL FOR UPDATE;
 -- The source must be this resident's current Form 1823; anything else is a mislink, not a draft.
 IF p_source_form_1823_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM form_1823_records f WHERE f.id=p_source_form_1823_id AND f.resident_id=r.id AND f.is_current AND f.deleted_at IS NULL
 ) THEN RAISE EXCEPTION 'The Form 1823 named is not this resident''s current form'; END IF;
 request_hash:=md5(jsonb_build_object('resident',p_resident_id,'previous',p_previous_id,'effective',p_effective,'review',p_review,'notes',p_notes,'items',p_items,'source_form_1823',p_source_form_1823_id)::text);
 IF EXISTS(SELECT 1 FROM care_plans WHERE id=p_id AND resident_id=r.id AND created_by=auth.uid()) THEN
  IF NOT EXISTS(SELECT 1 FROM care_plans WHERE id=p_id AND creation_request_hash=request_hash) THEN RAISE EXCEPTION 'This care-plan request was saved with different content. Reload before revising'; END IF;
  RETURN p_id;
 END IF;
 IF p_previous_id IS NULL AND EXISTS(SELECT 1 FROM care_plans WHERE resident_id=r.id AND deleted_at IS NULL AND status<>'archived') THEN RAISE EXCEPTION 'Open the existing care plan to create a revision'; END IF;
 IF p_previous_id IS NOT NULL THEN
  SELECT * INTO STRICT previous FROM care_plans WHERE id=p_previous_id AND resident_id=r.id AND deleted_at IS NULL;
  IF previous.status='archived' THEN RAISE EXCEPTION 'Open the current care-plan version to revise it'; END IF;
  IF EXISTS(SELECT 1 FROM care_plans WHERE previous_version_id=previous.id AND status IN('draft','under_review') AND deleted_at IS NULL) THEN RAISE EXCEPTION 'A revision is already awaiting clinical review'; END IF;
 END IF;
 INSERT INTO care_plans(id,resident_id,facility_id,organization_id,version,status,effective_date,review_due_date,notes,previous_version_id,created_by,creation_request_hash,source_form_1823_id)
 VALUES(p_id,r.id,r.facility_id,r.organization_id,coalesce(previous.version,0)+1,'under_review',p_effective,p_review,p_notes,p_previous_id,auth.uid(),request_hash,p_source_form_1823_id);
 FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
  IF nullif(trim(item->>'title'),'') IS NULL OR nullif(trim(item->>'description'),'') IS NULL THEN RAISE EXCEPTION 'Every care need requires a title and description'; END IF;
  INSERT INTO care_plan_items(care_plan_id,resident_id,facility_id,organization_id,category,title,description,assistance_level,frequency,goal,interventions,special_instructions,sort_order,created_by)
  VALUES(p_id,r.id,r.facility_id,r.organization_id,(item->>'category')::care_plan_item_category,item->>'title',item->>'description',(item->>'assistance_level')::assistance_level,item->>'frequency',item->>'goal',ARRAY(SELECT jsonb_array_elements_text(item->'interventions')),item->>'special_instructions',position,auth.uid());
  position:=position+1;
 END LOOP;
 RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.create_meeting_action(p_id uuid, p_meeting_id uuid, p_description text, p_assigned_to uuid, p_due_date date, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_actor public.user_profiles%ROWTYPE; v_meeting public.meetings%ROWTYPE; v_existing public.meeting_action_items%ROWTYPE;
BEGIN
  IF p_actor_id IS NULL OR p_id IS NULL OR p_due_date IS NULL OR length(trim(coalesce(p_description,'')))=0 THEN RAISE EXCEPTION 'Actor, description and due date required'; END IF;
  SELECT * INTO v_meeting FROM public.meetings WHERE id=p_meeting_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Meeting unavailable'; END IF;
  SELECT * INTO v_actor FROM public.user_profiles WHERE id=p_actor_id AND is_active AND deleted_at IS NULL;
  IF NOT FOUND OR v_actor.organization_id<>v_meeting.organization_id OR coalesce(v_actor.app_role::text,'') NOT IN('owner','org_admin','facility_admin','manager','coordinator','med_tech') THEN RAISE EXCEPTION 'Meeting action author is not authorized' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.facilities WHERE id=v_meeting.facility_id AND organization_id=v_actor.organization_id AND deleted_at IS NULL) OR (v_actor.app_role NOT IN('owner','org_admin') AND NOT EXISTS(SELECT 1 FROM public.user_facility_access WHERE user_id=p_actor_id AND facility_id=v_meeting.facility_id AND organization_id=v_actor.organization_id AND revoked_at IS NULL)) THEN RAISE EXCEPTION 'Meeting facility access required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_existing FROM public.meeting_action_items WHERE id=p_id;
  IF FOUND THEN
    IF v_existing.created_by IS DISTINCT FROM p_actor_id OR v_existing.meeting_id<>p_meeting_id OR v_existing.description<>trim(p_description) OR v_existing.assigned_to IS DISTINCT FROM p_assigned_to OR v_existing.due_date<>p_due_date THEN RAISE EXCEPTION 'Action identity already saved with different values'; END IF;
    RETURN p_id;
  END IF;
  IF p_assigned_to IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_facility_access a JOIN public.user_profiles p ON p.id=a.user_id WHERE a.user_id=p_assigned_to AND a.facility_id=v_meeting.facility_id AND a.revoked_at IS NULL AND p.organization_id=v_meeting.organization_id AND p.is_active AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Assignee unavailable in meeting facility'; END IF;
  INSERT INTO public.operation_task_instances(id,organization_id,facility_id,template_name,template_category,template_cadence_type,priority,assigned_shift_date,assigned_to,assigned_by,assigned_at,status,due_at,created_by)
    VALUES(p_id,v_meeting.organization_id,v_meeting.facility_id,'Meeting action: '||left(trim(p_description),160),'meeting_action','event_driven','normal',p_due_date,p_assigned_to,p_actor_id,now(),'pending',(p_due_date+time '23:59:59') AT TIME ZONE 'America/New_York',p_actor_id);
  INSERT INTO public.meeting_action_items(id,organization_id,facility_id,meeting_id,description,assigned_to,due_date,oce_task_instance_id,created_by,updated_by)
    VALUES(p_id,v_meeting.organization_id,v_meeting.facility_id,p_meeting_id,trim(p_description),p_assigned_to,p_due_date,p_id,p_actor_id,p_actor_id);
  RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.document_role_can_view_audience(p_audience text, p_user_role text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  SELECT
    CASE WHEN p_audience IS NULL OR p_audience = 'company_wide' THEN
      TRUE
    WHEN p_audience = 'facility_scoped' THEN
      p_user_role IN ('owner', 'org_admin', 'facility_admin', 'med_tech', 'caregiver', 'dietary', 'cook', 'maintenance_role')
    ELSE
      TRUE
    END;

$function$;

CREATE OR REPLACE FUNCTION public.haven_apply_approved_shift_swap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_request public.shift_assignments%ROWTYPE; v_cover public.shift_assignments%ROWTYPE; v_role text; v_cover_role text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  IF TG_OP='INSERT' THEN
    NEW.requesting_confirmed_at:=NULL; NEW.covering_confirmed_at:=NULL;
    IF NEW.status='approved' THEN RAISE EXCEPTION 'Participants must confirm before manager approval'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.requesting_staff_id IS DISTINCT FROM OLD.requesting_staff_id OR NEW.covering_staff_id IS DISTINCT FROM OLD.covering_staff_id OR NEW.requesting_assignment_id IS DISTINCT FROM OLD.requesting_assignment_id OR NEW.covering_assignment_id IS DISTINCT FROM OLD.covering_assignment_id THEN
    IF OLD.status='approved' THEN RAISE EXCEPTION 'Approved coverage is immutable'; END IF;
    NEW.requesting_confirmed_at:=NULL; NEW.covering_confirmed_at:=NULL;
  ELSE
    IF NEW.requesting_confirmed_at IS DISTINCT FROM OLD.requesting_confirmed_at THEN
      IF NOT EXISTS(SELECT 1 FROM public.staff WHERE id=NEW.requesting_staff_id AND user_id=auth.uid() AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Only the requesting employee may confirm'; END IF;
      NEW.requesting_confirmed_at:=now();
    END IF;
    IF NEW.covering_confirmed_at IS DISTINCT FROM OLD.covering_confirmed_at THEN
      IF NOT EXISTS(SELECT 1 FROM public.staff WHERE id=NEW.covering_staff_id AND user_id=auth.uid() AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Only the covering employee may confirm'; END IF;
      NEW.covering_confirmed_at:=now();
    END IF;
  END IF;
  IF NEW.eligibility_reviewed_at IS DISTINCT FROM OLD.eligibility_reviewed_at OR NEW.eligibility_reviewed_by IS DISTINCT FROM OLD.eligibility_reviewed_by THEN
    IF haven.app_role() NOT IN ('owner','org_admin','facility_admin','med_tech') THEN RAISE EXCEPTION 'Scheduling manager review required'; END IF;
    NEW.eligibility_reviewed_at:=clock_timestamp(); NEW.eligibility_reviewed_by:=auth.uid();
  END IF;
  IF NEW.status='approved' AND OLD.status<>'approved' THEN
    IF haven.app_role() NOT IN ('owner','org_admin','facility_admin','med_tech') THEN RAISE EXCEPTION 'Scheduling manager approval required'; END IF;
    IF NEW.eligibility_reviewed_by IS DISTINCT FROM auth.uid() OR NEW.eligibility_reviewed_at IS NULL OR NEW.eligibility_reviewed_at<now()-interval '5 minutes' THEN RAISE EXCEPTION 'Review required credentials, weekly hours and rest before applying coverage'; END IF;
    IF NEW.requesting_confirmed_at IS NULL OR NEW.covering_confirmed_at IS NULL OR NEW.covering_staff_id IS NULL OR NEW.covering_staff_id=NEW.requesting_staff_id THEN RAISE EXCEPTION 'Both distinct employees must confirm the proposed coverage'; END IF;
    -- Lock all involved assignments deterministically, then check the current ownership.
    PERFORM 1 FROM public.shift_assignments WHERE id IN (NEW.requesting_assignment_id,NEW.covering_assignment_id) ORDER BY id FOR UPDATE;
    SELECT * INTO v_request FROM public.shift_assignments WHERE id=NEW.requesting_assignment_id AND deleted_at IS NULL;
    IF NOT FOUND OR v_request.staff_id<>NEW.requesting_staff_id OR v_request.facility_id<>NEW.facility_id OR v_request.organization_id<>NEW.organization_id THEN RAISE EXCEPTION 'Requesting assignment changed or is unavailable'; END IF;
    SELECT staff_role::text INTO v_role FROM public.staff WHERE id=NEW.requesting_staff_id AND deleted_at IS NULL AND employment_status='active';
    SELECT staff_role::text INTO v_cover_role FROM public.staff WHERE id=NEW.covering_staff_id AND deleted_at IS NULL AND employment_status='active' AND facility_id=NEW.facility_id;
    IF v_role IS NULL OR v_cover_role IS DISTINCT FROM v_role THEN RAISE EXCEPTION 'Coverage requires an active employee with the same staffing role'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.staff_certifications WHERE staff_id=NEW.covering_staff_id AND deleted_at IS NULL) OR EXISTS(SELECT 1 FROM public.staff_certifications WHERE staff_id=NEW.covering_staff_id AND deleted_at IS NULL AND (status::text IN ('expired','revoked') OR expiration_date<v_request.shift_date)) THEN RAISE EXCEPTION 'Review missing or expired covering employee credentials'; END IF;
    IF NEW.covering_assignment_id IS NOT NULL THEN
      SELECT * INTO v_cover FROM public.shift_assignments WHERE id=NEW.covering_assignment_id AND deleted_at IS NULL;
      IF NOT FOUND OR v_cover.staff_id<>NEW.covering_staff_id OR v_cover.facility_id<>NEW.facility_id OR v_cover.organization_id<>NEW.organization_id THEN RAISE EXCEPTION 'Covering assignment changed or is unavailable'; END IF;
      IF EXISTS(SELECT 1 FROM public.shift_assignments WHERE staff_id=NEW.requesting_staff_id AND deleted_at IS NULL AND status::text NOT IN ('cancelled','no_show') AND id NOT IN(NEW.requesting_assignment_id,NEW.covering_assignment_id) AND shift_date BETWEEN v_cover.shift_date-1 AND v_cover.shift_date+1) THEN RAISE EXCEPTION 'Requesting employee has adjacent assignments; review rest and overlap before coverage'; END IF;
    END IF;
    IF EXISTS(SELECT 1 FROM public.shift_assignments WHERE staff_id=NEW.covering_staff_id AND deleted_at IS NULL AND status::text NOT IN ('cancelled','no_show') AND id<>NEW.requesting_assignment_id AND id IS DISTINCT FROM NEW.covering_assignment_id AND shift_date BETWEEN v_request.shift_date-1 AND v_request.shift_date+1) THEN RAISE EXCEPTION 'Covering employee has adjacent assignments; review rest and overlap before coverage'; END IF;
    UPDATE public.shift_assignments SET staff_id=NEW.covering_staff_id,updated_by=auth.uid() WHERE id=NEW.requesting_assignment_id;
    IF NEW.covering_assignment_id IS NOT NULL THEN UPDATE public.shift_assignments SET staff_id=NEW.requesting_staff_id,updated_by=auth.uid() WHERE id=NEW.covering_assignment_id; END IF;
    NEW.approved_by:=auth.uid(); NEW.approved_at:=now(); NEW.denied_reason:=NULL;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.haven_employee_file_command(p_staff_id uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s public.staff%ROWTYPE; q public.employee_file_requirements%ROWTYPE; r public.employee_file_records%ROWTYPE; a public.staff_attendance_events%ROWTYPE; d public.staff_discipline_records%ROWTYPE;
 v_manager boolean; v_self boolean; v_id uuid; v_result jsonb; v_role text; v_hash text; v_signed boolean; v_requested timestamptz; v_meeting timestamptz;
BEGIN
 SELECT * INTO s FROM public.staff WHERE id=p_staff_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT coalesce(haven.employee_scope(s.organization_id,s.facility_id),false) THEN RAISE EXCEPTION 'Staff unavailable' USING ERRCODE='42501'; END IF;
 v_manager:=haven.employee_manager(); v_self:=coalesce(s.user_id=auth.uid(),false);
 IF p_action='record_export' THEN
  IF NOT (v_self OR v_manager OR haven.employee_medical_reader(s.organization_id,s.facility_id) OR haven.app_role()::text IN('med_tech','coordinator')) THEN RAISE EXCEPTION 'Employee export access required' USING ERRCODE='42501'; END IF;
  v_id:=s.id; v_result:=jsonb_build_object('scope','personnel_checklist','requested_at',now());
 ELSIF p_action='record_download' THEN
  SELECT * INTO r FROM public.employee_file_records WHERE id=(p_payload->>'id')::uuid AND staff_id=s.id;
  IF NOT FOUND OR NOT haven.employee_record_readable(r.id) THEN RAISE EXCEPTION 'Document access required' USING ERRCODE='42501'; END IF;
  v_id:=r.id; v_result:=jsonb_build_object('scope','document_download_request','requested_at',now());
 ELSIF p_action IN('submit_record','attach_record','review_record','sign_record') THEN
  IF p_action='submit_record' THEN
   SELECT * INTO q FROM public.employee_file_requirements WHERE id=(p_payload->>'requirement_id')::uuid AND organization_id=s.organization_id AND facility_id=s.facility_id AND deleted_at IS NULL;
   IF NOT FOUND OR q.review_status<>'approved' OR NOT ('*'=ANY(q.applies_to_staff_roles) OR s.staff_role::text=ANY(q.applies_to_staff_roles)) THEN RAISE EXCEPTION 'Approved applicable requirement required'; END IF;
  ELSE
   SELECT * INTO r FROM public.employee_file_records WHERE id=(p_payload->>'id')::uuid AND staff_id=s.id AND deleted_at IS NULL FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Employee record unavailable'; END IF;
   SELECT * INTO q FROM public.employee_file_requirements WHERE id=r.requirement_id;
  END IF;
  IF q.category='medical' THEN
   IF NOT (v_self OR haven.employee_medical_reader(s.organization_id,s.facility_id)) THEN RAISE EXCEPTION 'Confidential medical access required' USING ERRCODE='42501'; END IF;
  ELSIF NOT(v_self OR v_manager OR (p_action='sign_record' AND haven.app_role()::text IN('med_tech','coordinator'))) THEN RAISE EXCEPTION 'Employee record access required' USING ERRCODE='42501'; END IF;
  IF p_action='submit_record' THEN
   IF (p_payload->>'completed_on')::date>(now() AT TIME ZONE 'America/New_York')::date THEN RAISE EXCEPTION 'Completion cannot be in the future'; END IF;
   INSERT INTO public.employee_file_records(id,organization_id,facility_id,staff_id,requirement_id,completed_on,expires_on,notes,evidence_reference,created_by)
   VALUES(coalesce((p_payload->>'id')::uuid,gen_random_uuid()),s.organization_id,s.facility_id,s.id,q.id,(p_payload->>'completed_on')::date,(p_payload->>'expires_on')::date,p_payload->>'notes',nullif(trim(p_payload->>'evidence_reference'),''),auth.uid()) RETURNING * INTO r;
   v_id:=r.id; v_result:=to_jsonb(r);
  ELSE
   IF r.status<>'submitted' THEN RAISE EXCEPTION 'Reviewed records are immutable; submit new evidence'; END IF;
   SELECT EXISTS(SELECT 1 FROM public.employee_file_signatures WHERE record_id=r.id) INTO v_signed;
   IF p_action='attach_record' THEN
    IF r.created_by<>auth.uid() OR v_signed OR r.storage_path IS NOT NULL THEN RAISE EXCEPTION 'Attachment is immutable or not owned by caller'; END IF;
    IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id=CASE WHEN q.category='medical' THEN 'employee-medical' ELSE 'employee-personnel' END AND o.name=p_payload->>'storage_path' AND o.name LIKE r.id::text||'/%') THEN RAISE EXCEPTION 'Uploaded record attachment required'; END IF;
    UPDATE public.employee_file_records SET storage_path=p_payload->>'storage_path',updated_at=now() WHERE id=r.id RETURNING * INTO r;
    v_id:=r.id; v_result:=to_jsonb(r);
   ELSIF p_action='sign_record' THEN
    v_role:=p_payload->>'functional_role';
    IF NOT coalesce(v_role=ANY(q.required_signers),false) THEN RAISE EXCEPTION 'Signer purpose not required'; END IF;
    IF v_role='provider' THEN RAISE EXCEPTION 'Provider signature requires source evidence and authorized review'; END IF;
    IF v_role='employee' THEN
     IF NOT v_self THEN RAISE EXCEPTION 'Employee must sign for themselves'; END IF;
    ELSE
     IF v_self OR NOT(haven.app_role()::text IN('owner','org_admin','facility_admin','manager','med_tech','coordinator')) THEN RAISE EXCEPTION 'Independent authorized countersigner required'; END IF;
     IF v_role IN('administrator','supervisor') AND NOT v_manager THEN RAISE EXCEPTION 'Manager signer required for supervisor or administrator'; END IF;
     IF v_role='trainer' AND NOT(v_manager OR haven.app_role()::text='med_tech') THEN RAISE EXCEPTION 'Authorized trainer required'; END IF;
    END IF;
    IF EXISTS(SELECT 1 FROM public.employee_file_signatures WHERE record_id=r.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'A signer cannot fulfill multiple purposes on one record'; END IF;
    v_hash:=encode(sha256(convert_to(jsonb_build_object('record_id',r.id,'requirement_id',q.id,'version',q.version,'content',q.content,'completed_on',r.completed_on,'expires_on',r.expires_on,'notes',r.notes,'storage_path',r.storage_path,'evidence_reference',r.evidence_reference)::text,'UTF8')),'hex');
    INSERT INTO public.employee_file_signatures(record_id,user_id,functional_role,signature_name,record_snapshot_hash) VALUES(r.id,auth.uid(),v_role,p_payload->>'signature_name',v_hash) RETURNING id,to_jsonb(employee_file_signatures.*) INTO v_id,v_result;
   ELSE
    IF q.category='medical' THEN
     IF NOT haven.employee_medical_reader(s.organization_id,s.facility_id) OR v_self THEN RAISE EXCEPTION 'Independent medical reviewer grant required'; END IF;
    ELSIF NOT v_manager OR v_self THEN RAISE EXCEPTION 'Independent manager review required'; END IF;
    IF p_payload->>'status' NOT IN('verified','rejected') OR p_payload->>'status' IS NULL THEN RAISE EXCEPTION 'Review status required'; END IF;
    IF length(trim(coalesce(p_payload->>'review_note','')))=0 THEN RAISE EXCEPTION 'Review note required'; END IF;
    IF p_payload->>'status'='verified' THEN
     IF r.completed_on IS NULL OR r.completed_on>(now() AT TIME ZONE 'America/New_York')::date THEN RAISE EXCEPTION 'Actual completion date required'; END IF;
     IF q.review_status<>'approved' THEN RAISE EXCEPTION 'Requirement no longer approved'; END IF;
     IF EXISTS(SELECT 1 FROM unnest(q.required_signers) purpose WHERE NOT EXISTS(SELECT 1 FROM public.employee_file_signatures sig WHERE sig.record_id=r.id AND sig.functional_role=purpose)) AND nullif(trim(r.evidence_reference),'') IS NULL THEN RAISE EXCEPTION 'Required signatures or documented signed source evidence required'; END IF;
    END IF;
    UPDATE public.employee_file_records SET status=p_payload->>'status',review_note=p_payload->>'review_note',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=r.id RETURNING * INTO r;
    v_id:=r.id; v_result:=to_jsonb(r);
   END IF;
  END IF;
 ELSIF p_action='record_duty' THEN
  IF NOT v_manager THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;
  IF (p_payload->>'occurred_at')::timestamptz>now() OR length(trim(coalesce(p_payload->>'evidence_note','')))=0 THEN RAISE EXCEPTION 'Actual event and evidence note required'; END IF;
  INSERT INTO public.employee_duty_events(staff_id,organization_id,facility_id,duty,occurred_at,evidence_note,recorded_by,readiness_snapshot) VALUES(s.id,s.organization_id,s.facility_id,p_payload->>'duty',(p_payload->>'occurred_at')::timestamptz,p_payload->>'evidence_note',auth.uid(),haven.employee_duty_readiness_snapshot(s.id,p_payload->>'duty')) RETURNING id,to_jsonb(employee_duty_events.*) INTO v_id,v_result;
 ELSIF p_action='record_attendance' THEN
  IF NOT v_manager THEN RAISE EXCEPTION 'Manager required' USING ERRCODE='42501'; END IF;
  IF (p_payload->>'occurred_at')::timestamptz>now() THEN RAISE EXCEPTION 'Attendance cannot be in future'; END IF;
  IF p_payload->>'shift_assignment_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.shift_assignments WHERE id=(p_payload->>'shift_assignment_id')::uuid AND staff_id=s.id AND facility_id=s.facility_id) THEN RAISE EXCEPTION 'Staff shift required'; END IF;
  INSERT INTO public.staff_attendance_events(staff_id,organization_id,facility_id,event_type,occurred_at,shift_assignment_id,reason,notes,minutes_deviation,notification_method,notification_minutes_before,created_by,updated_by)
  VALUES(s.id,s.organization_id,s.facility_id,(p_payload->>'event_type')::public.staff_attendance_event_type,(p_payload->>'occurred_at')::timestamptz,(p_payload->>'shift_assignment_id')::uuid,p_payload->>'reason',p_payload->>'notes',(p_payload->>'minutes_deviation')::integer,p_payload->>'notification_method',(p_payload->>'notification_minutes_before')::integer,auth.uid(),auth.uid()) RETURNING * INTO a;
  v_id:=a.id; v_result:=to_jsonb(a);
 ELSIF p_action='review_attendance' THEN
  IF NOT v_manager OR v_self THEN RAISE EXCEPTION 'Independent manager required' USING ERRCODE='42501'; END IF;
  SELECT * INTO a FROM public.staff_attendance_events WHERE id=(p_payload->>'id')::uuid AND staff_id=s.id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR a.review_status<>'pending' THEN RAISE EXCEPTION 'Pending attendance event required'; END IF;
  IF p_payload->>'review_status' NOT IN('counted','excluded') OR p_payload->>'review_status' IS NULL OR length(trim(coalesce(p_payload->>'review_reason','')))=0 THEN RAISE EXCEPTION 'Review classification and reason required'; END IF;
  UPDATE public.staff_attendance_events SET review_status=p_payload->>'review_status',review_reason=p_payload->>'review_reason',reviewed_by=auth.uid(),reviewed_at=now(),updated_by=auth.uid() WHERE id=a.id RETURNING * INTO a;
  v_id:=a.id; v_result:=to_jsonb(a);
 ELSIF p_action='record_corrective_action' THEN
  IF NOT v_manager OR v_self THEN RAISE EXCEPTION 'Independent manager required' USING ERRCODE='42501'; END IF;
  SELECT * INTO a FROM public.staff_attendance_events WHERE id=(p_payload->>'attendance_event_id')::uuid AND staff_id=s.id AND deleted_at IS NULL;
  IF NOT FOUND OR a.review_status<>'counted' THEN RAISE EXCEPTION 'Reviewed counted occurrence required'; END IF;
  IF length(trim(coalesce(p_payload->>'notes','')))=0 OR (p_payload->>'effective_date')::date>(now() AT TIME ZONE 'America/New_York')::date THEN RAISE EXCEPTION 'Documented decision and actual effective date required'; END IF;
  IF p_payload->>'coaching_form_document_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.documents WHERE id=(p_payload->>'coaching_form_document_id')::uuid AND workspace_id=s.organization_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Organization coaching document required'; END IF;
  INSERT INTO public.staff_discipline_records(organization_id,facility_id,staff_id,action,absence_count_at_action,tardy_count_at_action,notes,effective_date,attendance_event_id,coaching_form_document_id,copy_given_to_employee_at,created_by,updated_by)
  VALUES(s.organization_id,s.facility_id,s.id,(p_payload->>'action')::public.discipline_action,coalesce((p_payload->>'absence_count_at_action')::integer,0),coalesce((p_payload->>'tardy_count_at_action')::integer,0),p_payload->>'notes',coalesce((p_payload->>'effective_date')::date,(now() AT TIME ZONE 'America/New_York')::date),a.id,(p_payload->>'coaching_form_document_id')::uuid,(p_payload->>'copy_given_to_employee_at')::timestamptz,auth.uid(),auth.uid()) RETURNING * INTO d;
  v_id:=d.id; v_result:=to_jsonb(d);
 ELSIF p_action='retract_corrective_action' THEN
  IF haven.app_role()::text NOT IN('owner','org_admin') OR v_self THEN RAISE EXCEPTION 'Independent organization approver required' USING ERRCODE='42501'; END IF;
  SELECT * INTO d FROM public.staff_discipline_records WHERE id=(p_payload->>'id')::uuid AND staff_id=s.id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR d.retracted_at IS NOT NULL THEN RAISE EXCEPTION 'Unretracted corrective action required'; END IF;
  v_requested:=(p_payload->>'employee_requested_at')::timestamptz; v_meeting:=(p_payload->>'review_meeting_at')::timestamptz;
  IF length(trim(coalesce(p_payload->>'retraction_reason','')))=0 OR v_requested IS NULL OR v_meeting IS NULL OR v_requested>v_meeting OR v_meeting>now() THEN RAISE EXCEPTION 'Retraction reason, actual request and review meeting required'; END IF;
  UPDATE public.staff_discipline_records SET retracted_at=now(),retracted_by=auth.uid(),retraction_approved_by=auth.uid(),retraction_reason=p_payload->>'retraction_reason',employee_requested_at=v_requested,review_meeting_at=v_meeting,qualifying_period_start=(p_payload->>'qualifying_period_start')::date,qualifying_period_end=(p_payload->>'qualifying_period_end')::date,updated_by=auth.uid() WHERE id=d.id RETURNING * INTO d;
  v_id:=d.id; v_result:=to_jsonb(d);
 ELSE RAISE EXCEPTION 'Unsupported employee file command'; END IF;
 INSERT INTO public.employee_file_audit_events(organization_id,facility_id,actor_id,action,entity_id) VALUES(s.organization_id,s.facility_id,auth.uid(),p_action,v_id);
 RETURN v_result;
END $function$;

CREATE OR REPLACE FUNCTION public.haven_employee_file_staff(p_staff_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, first_name text, last_name text, staff_role text, hire_date date, employment_status text, facility_id uuid, user_id uuid, facility_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT s.id,s.first_name,s.last_name,s.staff_role::text,s.hire_date,s.employment_status::text,s.facility_id,s.user_id,f.name
 FROM public.staff s JOIN public.facilities f ON f.id=s.facility_id AND f.organization_id=s.organization_id
 WHERE s.deleted_at IS NULL AND f.deleted_at IS NULL AND haven.employee_scope(s.organization_id,s.facility_id)
 AND CASE WHEN p_staff_id IS NULL THEN
   s.user_id=auth.uid() OR haven.employee_medical_reader(s.organization_id,s.facility_id)
 ELSE s.id=p_staff_id AND (s.user_id=auth.uid() OR haven.employee_manager()
   OR haven.app_role()::text IN('med_tech','coordinator') OR haven.employee_medical_reader(s.organization_id,s.facility_id)) END
$function$;

CREATE OR REPLACE FUNCTION public.haven_record_tray_pass(p_ticket_id uuid, p_resident_id uuid, p_food_level integer, p_liquid_level integer, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.user_profiles%ROWTYPE;
  v_ticket public.tray_tickets%ROWTYPE;
  v_diet public.diet_orders%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_actor FROM public.user_profiles WHERE id = p_actor_id AND is_active AND deleted_at IS NULL;
  IF v_actor.app_role::text NOT IN ('dietary', 'cook','dietary_aide','manager','owner','org_admin','facility_admin') THEN
    RAISE EXCEPTION 'Not permitted to pass trays' USING ERRCODE='42501';
  END IF;
  SELECT * INTO STRICT v_ticket FROM public.tray_tickets WHERE id=p_ticket_id AND resident_id=p_resident_id AND organization_id=v_actor.organization_id FOR UPDATE;
  IF v_actor.app_role::text NOT IN ('owner','org_admin') AND NOT EXISTS (
    SELECT 1 FROM public.user_facility_access WHERE user_id=p_actor_id AND facility_id=v_ticket.facility_id AND organization_id=v_actor.organization_id AND revoked_at IS NULL
  ) THEN RAISE EXCEPTION 'No access to this facility' USING ERRCODE='42501'; END IF;
  IF v_ticket.status IN ('passed','delivered') AND v_ticket.passed_by=p_actor_id THEN RETURN v_ticket.id; END IF;
  IF v_ticket.status NOT IN ('queued','prepping','plating','plated') THEN RAISE EXCEPTION 'Tray cannot be passed from its current status'; END IF;
  SELECT * INTO v_diet FROM public.diet_orders WHERE resident_id=p_resident_id AND facility_id=v_ticket.facility_id AND organization_id=v_actor.organization_id AND active AND deleted_at IS NULL
    AND effective_from <= now() AND (effective_to IS NULL OR effective_to > now()) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No current active diet order. Contact the nurse.'; END IF;
  IF p_food_level IS DISTINCT FROM v_diet.iddsi_food_level OR p_liquid_level IS DISTINCT FROM v_diet.iddsi_liquid_level THEN
    RAISE EXCEPTION 'Checked levels do not match the current order. Contact the nurse.';
  END IF;
  IF (v_ticket.diet_order_snapshot->>'iddsi_food_level')::integer IS DISTINCT FROM v_diet.iddsi_food_level
    OR (v_ticket.diet_order_snapshot->>'iddsi_liquid_level')::integer IS DISTINCT FROM v_diet.iddsi_liquid_level
    OR v_ticket.diet_order_snapshot->>'diet_type' IS DISTINCT FROM v_diet.diet_type
    OR COALESCE(v_ticket.diet_order_snapshot->'allergies','[]'::jsonb) IS DISTINCT FROM to_jsonb(v_diet.allergies)
  THEN RAISE EXCEPTION 'Tray snapshot differs from the current diet order. Regenerate the tray before serving.'; END IF;
  UPDATE public.tray_tickets SET status='passed', iddsi_confirmed_food=true, iddsi_confirmed_liquid=true,
    allergen_check_passed=true, passed_by=p_actor_id, passed_at=now() WHERE id=p_ticket_id;
  INSERT INTO public.audit_log(table_name,record_id,action,new_data,user_id,organization_id,facility_id)
    VALUES('tray_tickets',p_ticket_id,'UPDATE',jsonb_build_object('event','tray_pass_verified','food_level',p_food_level,'liquid_level',p_liquid_level),p_actor_id,v_actor.organization_id,v_ticket.facility_id);
  RETURN p_ticket_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prepare_resident_record_intake(p_request_key text, p_facility_id uuid, p_title text, p_resident_id uuid DEFAULT NULL::uuid, p_admission_case_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a record; v public.resident_record_intakes; q haven.resident_record_intake_requests;
  h text; response jsonb;
BEGIN
  SELECT * INTO a FROM haven.current_authorized_actor() WHERE actor_is_managed LIMIT 1;
  IF a.actor_user_id IS NULL OR a.actor_role_text NOT IN ('owner','org_admin','facility_admin','med_tech')
     OR NOT haven.has_facility_access(p_facility_id) THEN
    RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501';
  END IF;
  IF p_request_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,159}$' OR length(btrim(coalesce(p_title,''))) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Valid request key and intake title are required' USING ERRCODE='22023';
  END IF;
  IF p_resident_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.residents r WHERE r.id=p_resident_id
      AND r.organization_id=a.actor_organization_id AND r.facility_id=p_facility_id AND r.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501';
  END IF;
  IF p_admission_case_id IS NOT NULL AND (p_resident_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.admission_cases c
      WHERE c.id=p_admission_case_id AND c.organization_id=a.actor_organization_id
      AND c.facility_id=p_facility_id AND c.resident_id=p_resident_id AND c.deleted_at IS NULL)) THEN
    RAISE EXCEPTION 'Resident intake scope unavailable' USING ERRCODE='42501';
  END IF;
  h:=encode(sha256(convert_to(jsonb_build_object('facility_id',p_facility_id,'title',btrim(p_title),
    'resident_id',p_resident_id,'admission_case_id',p_admission_case_id)::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(a.actor_user_id::text||'|'||p_request_key,1510));
  SELECT * INTO q FROM haven.resident_record_intake_requests
    WHERE actor_id=a.actor_user_id AND request_key=p_request_key FOR UPDATE;
  IF FOUND THEN
    IF q.operation<>'prepare_intake' OR q.request_hash<>h THEN
      RAISE EXCEPTION 'Resident intake request key content conflict' USING ERRCODE='23505';
    END IF;
    PERFORM haven.resident_record_intake_scope(q.intake_id,false);
    RETURN q.response||jsonb_build_object('replayed',true);
  END IF;
  INSERT INTO public.resident_record_intakes(
    organization_id,facility_id,resident_id,admission_case_id,title,state,created_by,updated_by
  ) VALUES(a.actor_organization_id,p_facility_id,p_resident_id,p_admission_case_id,btrim(p_title),
    CASE WHEN p_resident_id IS NULL THEN 'draft'::public.resident_record_intake_state ELSE 'uploading'::public.resident_record_intake_state END,a.actor_user_id,a.actor_user_id)
  RETURNING * INTO v;
  response:=jsonb_build_object('intake',to_jsonb(v),'replayed',false);
  INSERT INTO haven.resident_record_intake_requests(actor_id,intake_id,request_key,operation,request_hash,response,completed_at)
    VALUES(a.actor_user_id,v.id,p_request_key,'prepare_intake',h,response,clock_timestamp());
  RETURN response;
END
$function$;

CREATE OR REPLACE FUNCTION public.record_caregiver_emar_review(p_request_id uuid, p_medication_id uuid, p_scheduled_at timestamp with time zone, p_status text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE m resident_medications%ROWTYPE; existing emar_records%ROWTYPE; scheduled timestamptz; local_scheduled timestamp; tz text; result uuid;
BEGIN
 IF auth.uid() IS NULL OR haven.app_role() NOT IN('owner','org_admin','facility_admin','med_tech','caregiver','med_tech') OR p_status NOT IN('given','refused') THEN RAISE EXCEPTION 'Medication documentation authorization required'; END IF;
 SELECT * INTO STRICT m FROM resident_medications WHERE id=p_medication_id AND deleted_at IS NULL;
 IF m.status<>'active' THEN RAISE EXCEPTION 'The medication order is no longer active'; END IF;
 IF EXISTS(SELECT 1 FROM emar_records WHERE id=p_request_id AND administered_by=auth.uid()) THEN
  IF NOT EXISTS(SELECT 1 FROM emar_records WHERE id=p_request_id AND resident_medication_id=m.id AND status::text=p_status AND (m.frequency='prn' OR scheduled_time=p_scheduled_at) AND (p_status<>'refused' OR refusal_reason IS NOT DISTINCT FROM trim(p_reason)) AND (m.frequency<>'prn' OR prn_reason_given IS NOT DISTINCT FROM trim(p_reason))) THEN RAISE EXCEPTION 'This dose request was already saved with different content. Refresh the MAR before correcting'; END IF;
  RETURN p_request_id;
 END IF;
 IF (m.frequency='prn' OR p_status='refused') AND nullif(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'An indication or refusal reason is required'; END IF;
 IF p_status='given' THEN
  IF m.witness_required OR m.controlled_schedule<>'non_controlled' THEN RAISE EXCEPTION 'Use the witnessed medication pass with an authorized medication operator for this order'; END IF;
  IF EXISTS(SELECT 1 FROM pre_pass_holds h WHERE h.resident_id=m.resident_id AND h.active AND (h.resident_medication_id IS NULL OR h.resident_medication_id=m.id)) THEN RAISE EXCEPTION 'An active hold requires nurse resolution'; END IF;
 END IF;
 scheduled:=CASE WHEN m.frequency='prn' THEN now() ELSE p_scheduled_at END;
 IF scheduled IS NULL THEN RAISE EXCEPTION 'Scheduled administration time is required'; END IF;
 SELECT timezone INTO tz FROM facilities WHERE id=m.facility_id;
 local_scheduled:=scheduled AT TIME ZONE coalesce(tz,'America/New_York');
 IF m.frequency<>'prn' AND NOT EXISTS(SELECT 1 FROM emar_records WHERE resident_medication_id=m.id AND scheduled_time=scheduled AND status='scheduled' AND deleted_at IS NULL) THEN
  IF local_scheduled::date<m.start_date OR local_scheduled::date>(now() AT TIME ZONE coalesce(tz,'America/New_York'))::date OR (m.end_date IS NOT NULL AND local_scheduled::date>m.end_date) OR NOT coalesce(local_scheduled::time=ANY(m.scheduled_times),false) THEN RAISE EXCEPTION 'Scheduled time must match the prescribed medication schedule'; END IF;
  IF (m.frequency='weekly' AND (local_scheduled::date-m.start_date)%7<>0) OR (m.frequency='biweekly' AND (local_scheduled::date-m.start_date)%14<>0) OR (m.frequency='monthly' AND extract(day FROM local_scheduled)<>extract(day FROM m.start_date)) THEN RAISE EXCEPTION 'Scheduled date must match the prescribed medication frequency'; END IF;
 END IF;

 PERFORM pg_advisory_xact_lock(hashtextextended(m.id::text||'|'||extract(epoch FROM scheduled)::text,0));
 IF m.frequency<>'prn' THEN
  SELECT * INTO existing FROM emar_records WHERE resident_medication_id=m.id AND scheduled_time=scheduled AND NOT is_prn AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF existing.id IS NOT NULL AND existing.status<>'scheduled' THEN RAISE EXCEPTION 'This scheduled dose has already been resolved. Refresh the queue'; END IF;
 END IF;
 IF existing.id IS NOT NULL THEN
  UPDATE emar_records SET status=p_status::emar_status,actual_time=now(),administered_by=auth.uid(),refusal_reason=CASE WHEN p_status='refused' THEN trim(p_reason) END,updated_by=auth.uid() WHERE id=existing.id RETURNING id INTO result;
 ELSE
  INSERT INTO emar_records(id,resident_id,resident_medication_id,facility_id,organization_id,scheduled_time,actual_time,status,administered_by,is_prn,prn_reason_given,refusal_reason,created_by)
  VALUES(p_request_id,m.resident_id,m.id,m.facility_id,m.organization_id,scheduled,now(),p_status::emar_status,auth.uid(),m.frequency='prn',CASE WHEN m.frequency='prn' THEN trim(p_reason) END,CASE WHEN p_status='refused' THEN trim(p_reason) END,auth.uid()) RETURNING id INTO result;
 END IF;
 RETURN result;
END $function$;

CREATE OR REPLACE FUNCTION public.record_verbal_order_review(p_id uuid, p_action text, p_evidence text, p_signed_date date, p_medication_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE o verbal_orders%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR haven.app_role() NOT IN('owner','org_admin','facility_admin','med_tech') OR nullif(trim(p_evidence),'') IS NULL THEN RAISE EXCEPTION 'Clinical authorization and evidence are required'; END IF;
 SELECT * INTO STRICT o FROM verbal_orders WHERE id=p_id AND deleted_at IS NULL FOR UPDATE;
 IF p_action='signature' THEN
  IF p_signed_date IS NULL OR p_signed_date>current_date THEN RAISE EXCEPTION 'An actual physician signature date is required'; END IF;
  UPDATE verbal_orders SET cosignature_status='signed',cosigned_by=auth.uid(),cosigned_at=now(),physician_signed_date=p_signed_date,implementation_notes=concat_ws(E'\n',implementation_notes,'Signature evidence: '||p_evidence),updated_by=auth.uid() WHERE id=o.id;
 ELSIF p_action='implementation' THEN
  IF o.order_type IN('new_medication','dose_change','frequency_change','discontinue') AND NOT EXISTS(SELECT 1 FROM resident_medications m WHERE m.id=p_medication_id AND m.resident_id=o.resident_id AND m.facility_id=o.facility_id AND m.deleted_at IS NULL AND ((o.order_type='discontinue' AND m.status='discontinued') OR (o.order_type<>'discontinue' AND m.status='active'))) THEN RAISE EXCEPTION 'Choose the resulting medication order in the expected state'; END IF;
  UPDATE verbal_orders SET implemented=true,implemented_by=auth.uid(),implemented_at=now(),linked_medication_id=p_medication_id,implementation_notes=concat_ws(E'\n',implementation_notes,'Implementation evidence: '||p_evidence),updated_by=auth.uid() WHERE id=o.id;
 ELSE RAISE EXCEPTION 'Unsupported order review action'; END IF;
 RETURN o.id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_verified_med_pass_witness(p_pass_id uuid, p_actor_id uuid, p_witness_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE mp public.med_passes; sig_id uuid := gen_random_uuid();
BEGIN
  IF p_actor_id = p_witness_id THEN RAISE EXCEPTION 'Independent witness required'; END IF;
  SELECT * INTO STRICT mp FROM public.med_passes WHERE id=p_pass_id AND deleted_at IS NULL FOR UPDATE;
  IF mp.status NOT IN ('pending','overdue') OR mp.administered_by <> p_actor_id THEN RAISE EXCEPTION 'Pass unavailable'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.med_tech_shifts WHERE id=mp.shift_id AND user_id=p_actor_id AND status='active' AND deleted_at IS NULL
    AND facility_id=mp.facility_id AND organization_id=mp.organization_id) THEN RAISE EXCEPTION 'Active shift required'; END IF;
  IF (SELECT count(*) FROM public.user_profiles u WHERE u.id IN (p_actor_id,p_witness_id) AND u.is_active AND u.deleted_at IS NULL
    AND u.organization_id=mp.organization_id
    AND ((u.id=p_actor_id AND u.app_role IN ('med_tech','caregiver','med_tech'))
      OR (u.id=p_witness_id AND u.app_role IN ('med_tech','caregiver')))
    AND EXISTS (SELECT 1 FROM public.user_facility_access a WHERE a.user_id=u.id AND a.facility_id=mp.facility_id
      AND a.organization_id=mp.organization_id AND a.revoked_at IS NULL)) <> 2 THEN RAISE EXCEPTION 'Both staff must have clinical facility access'; END IF;
  INSERT INTO public.witness_signatures(id,organization_id,facility_id,med_pass_id,witness_user_id,signature_method,signature_hash,device_id)
    VALUES(sig_id,mp.organization_id,mp.facility_id,mp.id,p_witness_id,'password',
      encode(sha256(convert_to(jsonb_build_object('receipt',sig_id,'pass',mp.id,'version',mp.updated_at,'actor',p_actor_id,'witness',p_witness_id)::text,'UTF8')),'hex'),
      'server-credential-verification');
  RETURN sig_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resident_record_intake_snapshot(p_intake_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c jsonb; i public.resident_record_intakes; sources jsonb; facts jsonb; matches jsonb; counts jsonb; checklist jsonb;
BEGIN
  c:=haven.resident_record_intake_scope(p_intake_id,false);
  SELECT * INTO i FROM public.resident_record_intakes WHERE id=p_intake_id;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'source_order',s.source_order,'title',s.title,'original_filename',s.original_filename,
    'declared_mime',s.declared_mime,'declared_size_bytes',s.declared_size_bytes,'state',s.state,
    'revision',s.revision,'source_class',s.source_class,'document_type',s.document_type,
    'classification_confidence',s.classification_confidence,'classification_reason_code',s.classification_reason_code,
    'preflight_state',s.preflight_state,'credential_quarantined',s.credential_quarantined,
    'quarantine_reason_code',s.quarantine_reason_code,'page_count',s.page_count,
    'canonical_document_id',s.canonical_document_id,'promotion_mode',s.promotion_mode,
    'supersedes_document_id',s.supersedes_document_id,'finalized_at',s.finalized_at
  ) ORDER BY s.source_order),'[]') INTO sources
  FROM public.resident_record_intake_sources s WHERE s.intake_id=i.id AND s.deleted_at IS NULL;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',f.id,'fact_key',f.fact_key,'fact_version',f.fact_version,'field_code',f.field_code,
    'domain',f.domain,'structured_value',f.structured_value,'display_value',f.display_value,
    'source_id',f.source_id,'page_start',f.source_page_start,'page_end',f.source_page_end,
    'confidence',f.confidence,'conflict',f.conflict,'conflict_code',f.conflict_code,
    'required_reviewer',f.required_reviewer,'state',f.state,'revision',f.revision,
    'current_value',haven.resident_record_canonical_value(i.id,f.field_code,f.structured_value),
    'current_value_fingerprint',f.current_value_fingerprint,'canonical_fingerprint',f.current_value_fingerprint,
    'reviewed_by',f.reviewed_by,'reviewed_at',f.reviewed_at,'review_reason',f.review_reason,
    'applied_destination',f.applied_destination,'applied_record_id',f.applied_record_id
  ) ORDER BY f.created_at,f.id),'[]') INTO facts
  FROM public.resident_record_extracted_facts f WHERE f.intake_id=i.id AND f.deleted_at IS NULL;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',m.id,'candidate_kind',m.candidate_kind,'candidate_resident_id',m.candidate_resident_id,
    'candidate_referral_id',m.candidate_referral_id,'match_basis',m.match_basis,'confidence',m.confidence,
    'disposition',m.disposition,'reason',m.reason,'proposed_by',m.proposed_by,
    'candidate_first_name',coalesce(r.first_name,lead.first_name),
    'candidate_last_name',coalesce(r.last_name,lead.last_name),
    'candidate_date_of_birth',coalesce(r.date_of_birth,lead.date_of_birth),
    'candidate_status',coalesce(r.status::text,lead.status::text),
    'reviewed_by',m.reviewed_by,'reviewed_at',m.reviewed_at
  ) ORDER BY m.created_at,m.id),'[]') INTO matches
  FROM public.resident_record_intake_matches m
  LEFT JOIN public.residents r ON r.id=m.candidate_resident_id AND r.deleted_at IS NULL
  LEFT JOIN public.referral_leads lead ON lead.id=m.candidate_referral_id AND lead.deleted_at IS NULL
  WHERE m.intake_id=i.id AND m.deleted_at IS NULL;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'document_type',d.document_type,
    'required',d.required,'received_at',d.received_at,'waived_reason',d.waived_reason,
    'resident_document_id',d.resident_document_id,'state',CASE
      WHEN d.received_at IS NOT NULL THEN 'present' WHEN d.waived_reason IS NOT NULL THEN 'waived' ELSE 'missing' END)
    ORDER BY d.document_type::text),'[]') INTO checklist
  FROM public.admission_document_checklist_items d
  WHERE d.admission_case_id=i.admission_case_id AND d.deleted_at IS NULL;
  SELECT jsonb_build_object(
    'sources_total',count(*),'sources_finalized',count(*) FILTER(WHERE s.finalized_at IS NOT NULL),
    'sources_quarantined',count(*) FILTER(WHERE s.credential_quarantined),
    'sources_promoted',count(*) FILTER(WHERE s.canonical_document_id IS NOT NULL),
    'facts_total',(SELECT count(*) FROM public.resident_record_extracted_facts f WHERE f.intake_id=i.id AND f.deleted_at IS NULL),
    'facts_awaiting_review',(SELECT count(*) FROM public.resident_record_extracted_facts f WHERE f.intake_id=i.id AND f.deleted_at IS NULL AND f.state='proposed'),
    'facts_applied',(SELECT count(*) FROM public.resident_record_extracted_facts f WHERE f.intake_id=i.id AND f.deleted_at IS NULL AND f.state='applied'),
    'facts_conflicting',(SELECT count(*) FROM public.resident_record_extracted_facts f WHERE f.intake_id=i.id AND f.deleted_at IS NULL AND f.conflict AND f.state NOT IN('rejected','applied'))
  ) INTO counts FROM public.resident_record_intake_sources s WHERE s.intake_id=i.id AND s.deleted_at IS NULL;
  RETURN jsonb_build_object('intake',to_jsonb(i),'sources',sources,'facts',facts,'matches',matches,'checklist',checklist,
    'counts',counts,'can',jsonb_build_object('read',true,'manage',true,
      'clinical',c->>'role'='med_tech','payer',c->>'role' IN ('owner','org_admin','facility_admin'),
      'legal',c->>'role' IN ('owner','org_admin','facility_admin')));
END
$function$;

CREATE OR REPLACE FUNCTION public.save_medication_order_review(p_id uuid, p_resident_id uuid, p_previous_id uuid, p_action text, p_reason text, p_order jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r residents%ROWTYPE; previous resident_medications%ROWTYPE; m resident_medications%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR haven.app_role() NOT IN('owner','org_admin','facility_admin','med_tech') THEN RAISE EXCEPTION 'Authorized clinical order role required'; END IF;
 IF nullif(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Order evidence or change reason is required'; END IF;
 SELECT * INTO STRICT r FROM residents WHERE id=p_resident_id AND deleted_at IS NULL FOR UPDATE;
 IF EXISTS(SELECT 1 FROM resident_medications WHERE id=p_id AND resident_id=r.id AND created_by=auth.uid()) THEN
  IF NOT EXISTS(SELECT 1 FROM resident_medications WHERE id=p_id AND creation_request_hash=md5(jsonb_build_object('previous',p_previous_id,'action',p_action,'reason',p_reason,'order',p_order)::text)) THEN RAISE EXCEPTION 'This medication request was saved with different content. Reload the order before revising'; END IF;
  RETURN p_id;
 END IF;
 IF p_previous_id IS NOT NULL THEN SELECT * INTO STRICT previous FROM resident_medications WHERE id=p_previous_id AND resident_id=r.id AND deleted_at IS NULL FOR UPDATE; END IF;
 IF p_action='discontinue' THEN
  IF previous.id IS NULL THEN RAISE EXCEPTION 'Choose an existing medication'; END IF;
  UPDATE resident_medications SET status='discontinued',discontinued_date=current_date,discontinued_reason=p_reason,discontinued_by=auth.uid(),updated_by=auth.uid() WHERE id=previous.id;
  RETURN previous.id;
 END IF;
 IF p_action<>'save' THEN RAISE EXCEPTION 'Unsupported order action'; END IF;
 IF previous.id IS NOT NULL AND previous.status<>'active' THEN RAISE EXCEPTION 'Refresh before revising this inactive order'; END IF;
 m:=jsonb_populate_record(previous,p_order);
 IF nullif(trim(m.medication_name),'') IS NULL OR nullif(trim(m.strength),'') IS NULL OR nullif(trim(m.prescriber_name),'') IS NULL OR nullif(trim(m.instructions),'') IS NULL OR m.order_date IS NULL OR m.start_date IS NULL THEN RAISE EXCEPTION 'Medication, dose/strength, instructions, prescriber and dates are required'; END IF;
 IF m.frequency<>'prn' AND coalesce(array_length(m.scheduled_times,1),0)=0 THEN RAISE EXCEPTION 'Scheduled orders require explicit administration times'; END IF;
 IF m.frequency='prn' AND nullif(trim(m.prn_max_frequency),'') IS NULL THEN RAISE EXCEPTION 'PRN order restrictions are required'; END IF;
 INSERT INTO resident_medications(id,resident_id,facility_id,organization_id,medication_name,generic_name,strength,form,route,frequency,frequency_detail,scheduled_times,instructions,indication,prescriber_name,prescriber_phone,pharmacy_name,order_date,start_date,end_date,controlled_schedule,status,order_source,order_document_id,prn_reason,prn_max_frequency,prn_effectiveness_check_minutes,previous_medication_id,created_by,witness_required,geofence_enforced,creation_request_hash)
 VALUES(p_id,r.id,r.facility_id,r.organization_id,m.medication_name,m.generic_name,m.strength,m.form,m.route,m.frequency,m.frequency_detail,m.scheduled_times,m.instructions,m.indication,m.prescriber_name,m.prescriber_phone,m.pharmacy_name,m.order_date,m.start_date,m.end_date,m.controlled_schedule,'active',p_reason,m.order_document_id,m.prn_reason,m.prn_max_frequency,m.prn_effectiveness_check_minutes,previous.id,auth.uid(),coalesce(m.witness_required,false) OR m.controlled_schedule<>'non_controlled',coalesce(m.geofence_enforced,true),md5(jsonb_build_object('previous',p_previous_id,'action',p_action,'reason',p_reason,'order',p_order)::text));
 IF previous.id IS NOT NULL THEN UPDATE resident_medications SET status='discontinued',discontinued_date=current_date,discontinued_reason='Superseded: '||p_reason,discontinued_by=auth.uid(),updated_by=auth.uid() WHERE id=previous.id; END IF;
 RETURN p_id;
END $function$;

CREATE OR REPLACE FUNCTION public.stage_resident_record_parse_result(p_intake_id uuid, p_source_id uuid, p_run_id uuid, p_request_key text, p_expected_revision uuid, p_actor_id uuid, p_provider text, p_model text, p_model_version text, p_prompt_hash text, p_response_hash text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i public.resident_record_intakes; s public.resident_record_intake_sources;
  a public.user_profiles; run public.resident_record_parse_runs; h text; item jsonb;
  fact_ids jsonb:='[]'; fact_id uuid; page_count integer; result_class text;
BEGIN
  IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Server parser staging required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO a FROM public.user_profiles WHERE id=p_actor_id AND is_active AND deleted_at IS NULL FOR SHARE;
  SELECT * INTO i FROM public.resident_record_intakes WHERE id=p_intake_id AND deleted_at IS NULL FOR UPDATE;
  IF a.id IS NULL OR i.id IS NULL OR a.organization_id<>i.organization_id
     OR a.app_role NOT IN ('owner','org_admin','facility_admin','med_tech')
     OR (a.app_role NOT IN ('owner','org_admin') AND NOT EXISTS(SELECT 1 FROM public.user_facility_access ufa
       WHERE ufa.user_id=a.id AND ufa.organization_id=i.organization_id AND ufa.facility_id=i.facility_id
         AND ufa.revoked_at IS NULL)) THEN
    RAISE EXCEPTION 'Parser actor authority changed' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM public.resident_record_intake_sources WHERE id=p_source_id AND intake_id=i.id
    AND organization_id=i.organization_id AND facility_id=i.facility_id AND deleted_at IS NULL FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Resident source unavailable' USING ERRCODE='42501'; END IF;
  h:=encode(sha256(convert_to(jsonb_build_object('intake_id',p_intake_id,'source_id',p_source_id,
    'expected_revision',p_expected_revision,'provider',p_provider,'model',p_model,'model_version',p_model_version,
    'prompt_hash',p_prompt_hash,'response_hash',p_response_hash)::text,'UTF8')),'hex');
  SELECT * INTO run FROM public.resident_record_parse_runs WHERE requested_by=p_actor_id AND request_key=p_request_key FOR UPDATE;
  IF FOUND THEN
    IF run.request_hash<>h OR run.id<>p_run_id OR run.source_id<>p_source_id THEN
      RAISE EXCEPTION 'Parse request key content conflict' USING ERRCODE='23505';
    END IF;
    SELECT coalesce(jsonb_agg(f.id ORDER BY f.created_at),'[]') INTO fact_ids
      FROM public.resident_record_extracted_facts f WHERE f.parse_run_id=run.id;
    RETURN jsonb_build_object('run_id',run.id,'source_id',run.source_id,'fact_ids',fact_ids,'state',run.state,'replayed',true);
  END IF;
  IF s.revision<>p_expected_revision OR s.finalized_at IS NULL OR s.state NOT IN ('finalized','ready_to_parse','parsing','review')
     OR s.preflight_state NOT IN ('safe','overridden') OR s.credential_quarantined THEN
    RAISE EXCEPTION 'Source is not currently authorized for parsing' USING ERRCODE='55000';
  END IF;
  IF p_request_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,159}$'
     OR p_prompt_hash!~'^[0-9a-f]{64}$' OR p_response_hash!~'^[0-9a-f]{64}$'
     OR jsonb_typeof(p_result)<>'object' THEN RAISE EXCEPTION 'Invalid parser receipt' USING ERRCODE='22023'; END IF;
  result_class:=p_result->>'source_class';
  IF result_class NOT IN ('resident','facility','employee','other_resident','credential_secret','unreadable','unsupported') THEN
    RAISE EXCEPTION 'Parser returned an unsupported source class' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.resident_record_parse_runs(id,intake_id,source_id,organization_id,facility_id,
    request_key,request_hash,provider,model,model_version,prompt_hash,response_hash,state,requested_by)
  VALUES(p_run_id,i.id,s.id,i.organization_id,i.facility_id,p_request_key,h,btrim(p_provider),btrim(p_model),
    nullif(btrim(p_model_version),''),lower(p_prompt_hash),lower(p_response_hash),'running',a.id);
  IF result_class='credential_secret' OR NOT haven.resident_record_payload_safe(p_result) THEN
    UPDATE public.resident_record_intake_sources SET source_class='credential_secret',credential_quarantined=true,
      preflight_state='credential_detected',quarantine_reason_code='provider_credential_indicator',
      state='quarantined',revision=gen_random_uuid(),parser_metadata='{}' WHERE id=s.id;
    UPDATE public.resident_record_parse_runs SET state='quarantined',error_code='credential_detected_provider',completed_at=clock_timestamp()
      WHERE id=p_run_id;
    UPDATE public.resident_record_intakes SET quarantined_source_count=(SELECT count(*) FROM public.resident_record_intake_sources x
      WHERE x.intake_id=i.id AND x.credential_quarantined AND x.deleted_at IS NULL),state='review',revision=gen_random_uuid() WHERE id=i.id;
    RETURN jsonb_build_object('run_id',p_run_id,'source_id',s.id,'fact_ids','[]'::jsonb,'state','quarantined','replayed',false);
  END IF;
  IF result_class='resident' AND NOT haven.resident_record_document_type_allowed(p_result->>'document_type') THEN
    RAISE EXCEPTION 'Parser returned an unsupported resident document type' USING ERRCODE='22023';
  END IF;
  page_count:=coalesce((p_result->>'page_count')::integer,jsonb_array_length(coalesce(p_result->'pages','[]')),
    CASE WHEN s.declared_mime<>'application/pdf' THEN 1 END);
  IF page_count IS NULL OR page_count<1 OR jsonb_array_length(coalesce(p_result->'pages','[]'))<>page_count THEN
    RAISE EXCEPTION 'Parser must classify every source page' USING ERRCODE='22023';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_result->'pages') LOOP
    IF (item->>'page_number')::integer NOT BETWEEN 1 AND page_count
       OR item->>'source_class' NOT IN ('resident','facility','employee','other_resident','credential_secret','unreadable','unsupported')
       OR item->>'disposition' NOT IN ('resident_eligible','excluded','quarantined','unreadable')
       OR (item->>'source_class'='resident' AND NOT haven.resident_record_document_type_allowed(item->>'document_type')) THEN
      RAISE EXCEPTION 'Parser returned an invalid page classification' USING ERRCODE='22023';
    END IF;
    INSERT INTO public.resident_record_intake_pages(intake_id,source_id,organization_id,facility_id,page_number,
      source_class,document_type,disposition,confidence,reason_code,parse_run_id,created_by)
    VALUES(i.id,s.id,i.organization_id,i.facility_id,(item->>'page_number')::integer,
      (item->>'source_class')::public.resident_record_source_class,item->>'document_type',
      (item->>'disposition')::public.resident_record_page_disposition,(item->>'confidence')::numeric,
      nullif(item->>'reason_code',''),p_run_id,a.id)
    ON CONFLICT(source_id,page_number) DO UPDATE SET
      source_class=EXCLUDED.source_class,document_type=EXCLUDED.document_type,
      disposition=EXCLUDED.disposition,confidence=EXCLUDED.confidence,
      reason_code=EXCLUDED.reason_code,parse_run_id=EXCLUDED.parse_run_id,
      revision=gen_random_uuid(),created_at=clock_timestamp(),created_by=EXCLUDED.created_by,deleted_at=NULL;
  END LOOP;
  UPDATE public.resident_record_extracted_facts SET state='superseded',reviewed_by=a.id,
    reviewed_at=clock_timestamp(),review_reason='Superseded by reparse',revision=gen_random_uuid()
    WHERE source_id=s.id AND state='proposed' AND deleted_at IS NULL;
  FOR item IN SELECT value FROM jsonb_array_elements(coalesce(p_result->'facts','[]')) LOOP
    IF NOT haven.resident_record_field_allowed(item->>'field_code')
       OR item->>'domain' NOT IN ('demographics','clinical','payer','legal','authority','admission','contact','screening')
       OR item->'structured_value' IS NULL OR length(item->>'display_value') NOT BETWEEN 1 AND 2000
       OR ((item->>'field_code')='resident.ssn_last_four' AND (item#>>'{structured_value,value}')!~'^[0-9]{4}$') THEN
      RAISE EXCEPTION 'Parser returned an invalid controlled fact' USING ERRCODE='22023';
    END IF;
    fact_id:=gen_random_uuid();
    INSERT INTO public.resident_record_extracted_facts(id,intake_id,source_id,parse_run_id,organization_id,facility_id,
      field_code,domain,structured_value,display_value,source_page_start,source_page_end,confidence,
      current_value_fingerprint,conflict,conflict_code,required_reviewer,proposal_origin,proposed_by)
    VALUES(fact_id,i.id,s.id,p_run_id,i.organization_id,i.facility_id,item->>'field_code',item->>'domain',
      item->'structured_value',item->>'display_value',nullif(item->>'page_start','')::integer,
      nullif(item->>'page_end','')::integer,nullif(item->>'confidence','')::numeric,
      haven.resident_record_canonical_fingerprint(i.id,item->>'field_code',item->'structured_value'),
      coalesce((item->>'conflict')::boolean,false),nullif(item->>'conflict_code',''),
      haven.resident_record_expected_reviewer(item->>'field_code'),'provider',a.id);
    INSERT INTO public.resident_record_fact_events(intake_id,fact_id,organization_id,facility_id,event_type,fact_revision,actor_id,metadata)
      SELECT i.id,fact_id,i.organization_id,i.facility_id,'proposed',f.revision,a.id,
        jsonb_build_object('origin','provider','parse_run_id',p_run_id) FROM public.resident_record_extracted_facts f WHERE f.id=fact_id;
    fact_ids:=fact_ids||to_jsonb(fact_id);
  END LOOP;
  UPDATE public.resident_record_intake_sources SET source_class=result_class::public.resident_record_source_class,
    document_type=CASE WHEN result_class='resident' THEN p_result->>'document_type' END,
    classification_confidence=nullif(p_result->>'confidence','')::numeric,
    classification_reason_code=nullif(p_result->>'reason_code',''),page_count=page_count,
    state=CASE WHEN result_class='resident' THEN 'review'::public.resident_record_source_state ELSE 'excluded'::public.resident_record_source_state END,
    revision=gen_random_uuid(),parser_metadata=jsonb_build_object('provider',p_provider,'model',p_model,'run_id',p_run_id)
    WHERE id=s.id;
  UPDATE public.resident_record_parse_runs SET state='succeeded',completed_at=clock_timestamp() WHERE id=p_run_id;
  UPDATE public.resident_record_intakes SET parser_state='complete',state=CASE WHEN resident_id IS NULL THEN 'match_required'::public.resident_record_intake_state ELSE 'review'::public.resident_record_intake_state END,
    revision=gen_random_uuid() WHERE id=i.id;
  RETURN jsonb_build_object('run_id',p_run_id,'source_id',s.id,'fact_ids',fact_ids,'state','succeeded','replayed',false);
END
$function$;

CREATE OR REPLACE FUNCTION public.submit_care_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text := haven.app_role()::text;
  v_org uuid := haven.organization_id();
  v_client_event_id uuid;
  v_facility_id uuid;
  v_resident_id uuid;
  v_kind text;
  v_answers jsonb;
  v_note text;
  v_occurred_at timestamptz;
  v_location_code text;
  v_location_label text;
  v_captured_offline boolean;
  v_tz text;
  v_time_label text;
  v_hour integer;
  v_shift shift_type;
  v_existing record;
  v_context jsonb;
  v_derived jsonb;
  v_level integer;
  v_derived_level integer;
  v_final_level incident_severity;
  v_derived_sev incident_severity;
  v_category incident_category;
  v_flags jsonb;
  v_sentence text;
  v_worried boolean;
  v_care_event_id uuid;
  v_behavioral_log_id uuid;
  v_condition_change_id uuid;
  v_incident_id uuid;
  v_incident_number text;
  v_immediate_actions text;
  v_injury_occurred boolean;
  v_injury_severity text;
  v_injury_description text;
  v_where text;
  v_hurt text;
  v_what text;
  v_touched text;
  v_first_sign text;
  v_seen_labels text;
  v_proto record;
  v_due timestamptz;
  v_offset integer;
  v_assignee uuid;
  v_policy record;
  v_level_word text;
  v_tile_word text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF v_role IS NULL OR v_role NOT IN ('owner','org_admin','facility_admin','manager','admin_assistant','coordinator','med_tech','caregiver','med_tech') THEN
    RAISE EXCEPTION 'care_event: forbidden';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'care_event: payload must be an object';
  END IF;

  PERFORM set_config('haven.care_event_definer', '1', true);

  BEGIN
    v_client_event_id := (p_payload ->> 'client_event_id')::uuid;
    v_facility_id := (p_payload ->> 'facility_id')::uuid;
    v_resident_id := NULLIF(p_payload ->> 'resident_id', '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'care_event: invalid identifier in payload';
  END;
  IF v_client_event_id IS NULL THEN
    RAISE EXCEPTION 'care_event: client_event_id required';
  END IF;
  IF v_facility_id IS NULL THEN
    RAISE EXCEPTION 'care_event: facility_id required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.facilities f
    WHERE f.id = v_facility_id AND f.organization_id = v_org AND f.deleted_at IS NULL
  ) OR v_facility_id NOT IN (SELECT haven.accessible_facility_ids()) THEN
    RAISE EXCEPTION 'care_event: forbidden';
  END IF;

  v_kind := p_payload ->> 'kind';
  IF v_kind IS NULL OR v_kind NOT IN ('fall','injury_found','condition_change','behavior','wandering','medication','family_complaint','environment') THEN
    RAISE EXCEPTION 'care_event: unknown kind';
  END IF;

  IF v_resident_id IS NULL AND v_kind <> 'environment' THEN
    RAISE EXCEPTION 'care_event: resident required';
  END IF;
  IF v_resident_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.residents r
    WHERE r.id = v_resident_id AND r.facility_id = v_facility_id AND r.organization_id = v_org AND r.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'care_event: resident not at facility';
  END IF;

  -- Idempotent replay: same organization and client_event_id returns the same receipt.
  SELECT ce.id, ce.final_level, ce.incident_id
    INTO v_existing
  FROM public.care_events ce
  WHERE ce.organization_id = v_org AND ce.client_event_id = v_client_event_id;
  IF v_existing.id IS NOT NULL THEN
    RETURN public.care_event_receipt(v_existing.id, true);
  END IF;

  v_answers := CASE WHEN jsonb_typeof(p_payload -> 'answers') = 'object' THEN p_payload -> 'answers' ELSE '{}'::jsonb END;
  v_note := NULLIF(btrim(COALESCE(p_payload ->> 'note', '')), '');
  v_occurred_at := COALESCE(NULLIF(p_payload ->> 'occurred_at', '')::timestamptz, now());
  v_location_code := NULLIF(btrim(COALESCE(p_payload ->> 'location_code', '')), '');
  v_captured_offline := COALESCE((p_payload ->> 'captured_offline')::boolean, false);
  v_worried := lower(COALESCE(v_answers ->> 'worried', 'false')) = 'true';

  SELECT COALESCE(f.timezone, 'America/New_York') INTO v_tz FROM public.facilities f WHERE f.id = v_facility_id;

  IF v_location_code IS NOT NULL THEN
    SELECT ov.display_label INTO v_location_label
    FROM public.observation_vocab ov
    WHERE ov.organization_id = v_org
      AND ov.field_name = 'location'
      AND ov.value_code = v_location_code
      AND ov.active
      AND ov.deleted_at IS NULL
      AND (ov.facility_id = v_facility_id OR ov.facility_id IS NULL)
    ORDER BY ov.facility_id NULLS LAST
    LIMIT 1;
  END IF;

  v_time_label := to_char(v_occurred_at AT TIME ZONE v_tz, 'FMHH12:MI AM');
  v_hour := EXTRACT(HOUR FROM (v_occurred_at AT TIME ZONE v_tz))::integer;
  v_shift := CASE WHEN v_hour >= 7 AND v_hour < 15 THEN 'day' WHEN v_hour >= 15 AND v_hour < 23 THEN 'evening' ELSE 'night' END;

  v_context := jsonb_build_object(
    'active_watch', v_resident_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.resident_watch_instances w
      WHERE w.resident_id = v_resident_id
        AND w.deleted_at IS NULL
        AND w.status IN ('active','pending_approval')
        AND (w.ends_at IS NULL OR w.ends_at > now())),
    'elopement_risk', COALESCE((SELECT r.elopement_risk FROM public.residents r WHERE r.id = v_resident_id), false),
    'prior_unexplained_bruise_30d', v_resident_id IS NOT NULL AND (
      EXISTS (
        SELECT 1 FROM public.care_events ce
        WHERE ce.resident_id = v_resident_id
          AND ce.category = 'unexplained_bruise'
          AND ce.deleted_at IS NULL
          AND ce.occurred_at >= v_occurred_at - interval '30 days'
          AND ce.client_event_id <> v_client_event_id)
      OR EXISTS (
        SELECT 1 FROM public.incidents i
        WHERE i.resident_id = v_resident_id
          AND i.category = 'unexplained_bruise'
          AND i.deleted_at IS NULL
          AND i.occurred_at >= v_occurred_at - interval '30 days')),
    'location_label', v_location_label,
    'time_label', v_time_label
  );

  v_derived := public.care_event_derive(v_kind, v_answers, v_context);
  v_level := (v_derived ->> 'level')::integer;
  v_derived_level := (v_derived ->> 'derived_level')::integer;
  v_final_level := ('level_' || v_level)::incident_severity;
  v_derived_sev := ('level_' || v_derived_level)::incident_severity;
  v_category := (v_derived ->> 'category')::incident_category;
  v_flags := v_derived -> 'flags';
  v_sentence := v_derived ->> 'sentence';

  INSERT INTO public.care_events (
    organization_id, facility_id, resident_id, client_event_id, kind, answers,
    derived_level, final_level, level_bumped_by_reporter, category, flags, sentence, note,
    occurred_at, discovered_at, shift, location_code, reported_by, captured_offline
  ) VALUES (
    v_org, v_facility_id, v_resident_id, v_client_event_id, v_kind, v_answers,
    v_derived_sev, v_final_level, v_worried, v_category, v_flags, v_sentence, v_note,
    v_occurred_at, now(), v_shift, v_location_code, v_uid, v_captured_offline
  )
  RETURNING id INTO v_care_event_id;

  v_hurt := v_answers ->> 'hurt';
  v_what := v_answers ->> 'what';
  v_touched := v_answers ->> 'touched';
  v_where := v_answers ->> 'where';

  -- ---- behavioral_logs ----------------------------------------------------
  IF v_kind = 'behavior' THEN
    INSERT INTO public.behavioral_logs (
      resident_id, facility_id, organization_id, occurred_at, shift, logged_by,
      behavior, behavior_type, injury_occurred, involved_staff, notes
    ) VALUES (
      v_resident_id, v_facility_id, v_org, v_occurred_at, v_shift, v_uid,
      v_sentence, COALESCE(v_what, 'other'),
      v_touched IS NOT NULL AND v_touched <> 'no_one',
      CASE WHEN v_touched = 'staff' THEN '{}'::uuid[] ELSE NULL END,
      v_note
    )
    RETURNING id INTO v_behavioral_log_id;
    UPDATE public.care_events SET behavioral_log_id = v_behavioral_log_id WHERE id = v_care_event_id;
  END IF;

  -- ---- condition_changes (BEFORE INSERT trigger raises the care plan alert)
  IF v_kind = 'condition_change' THEN
    SELECT x INTO v_first_sign
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_answers -> 'signs') = 'array' THEN v_answers -> 'signs' ELSE '[]'::jsonb END) AS t(x)
    LIMIT 1;
    INSERT INTO public.condition_changes (
      resident_id, facility_id, organization_id, reported_at, reported_by, shift,
      change_type, description, severity
    ) VALUES (
      v_resident_id, v_facility_id, v_org, v_occurred_at, v_uid, v_shift,
      COALESCE(v_first_sign, 'not_themselves'), v_sentence,
      CASE WHEN v_level >= 4 THEN 'severe' WHEN v_level = 3 THEN 'moderate' ELSE 'mild' END
    )
    RETURNING id INTO v_condition_change_id;
    UPDATE public.care_events SET condition_change_id = v_condition_change_id WHERE id = v_care_event_id;
  END IF;

  -- ---- incidents for Level 2 and above --------------------------------------
  IF v_level >= 2 THEN
    v_incident_number := public.allocate_incident_number(v_facility_id);

    v_immediate_actions := CASE
      WHEN v_kind = 'fall' AND v_answers ->> 'going_out' = 'yes' THEN 'Emergency care requested.'
      WHEN v_kind = 'fall' AND v_hurt = 'badly' THEN 'Emergency care requested.'
      WHEN v_kind = 'fall' AND v_hurt = 'a_little' THEN 'First aid given.'
      WHEN v_kind = 'medication' AND v_answers ->> 'reaction' = 'yes' THEN 'Administrator alerted for medical follow-up.'
      WHEN v_kind = 'wandering' AND v_where = 'not_found' THEN 'Search started and Administrator alerted.'
      ELSE 'Resident checked and made safe. Administrator alerted.'
    END;

    v_injury_occurred := CASE
      WHEN v_kind = 'fall' THEN v_hurt IS NOT NULL AND v_hurt <> 'not_hurt'
      WHEN v_kind = 'injury_found' THEN true
      WHEN v_kind = 'wandering' THEN COALESCE(v_hurt = 'yes', false)
      WHEN v_kind = 'behavior' THEN v_touched IS NOT NULL AND v_touched <> 'no_one'
      ELSE false
    END;

    v_injury_severity := CASE
      WHEN v_kind = 'fall' AND v_hurt = 'a_little' THEN 'minor'
      WHEN v_kind = 'fall' AND v_hurt = 'badly' THEN 'major'
      WHEN v_kind = 'injury_found' AND v_answers ->> 'care' = 'first_aid_enough' THEN 'minor'
      WHEN v_kind = 'injury_found' AND v_answers ->> 'care' = 'more_than_first_aid' THEN 'major'
      ELSE NULL
    END;

    IF v_kind = 'injury_found' AND jsonb_typeof(v_answers -> 'seen') = 'array' THEN
      SELECT string_agg(CASE x
        WHEN 'bruise' THEN 'bruise'
        WHEN 'skin_tear' THEN 'skin tear or cut'
        WHEN 'burn' THEN 'burn'
        WHEN 'swelling_pain' THEN 'swelling or pain'
        WHEN 'other' THEN 'other' END, ', ' ORDER BY ord)
        INTO v_seen_labels
      FROM jsonb_array_elements_text(v_answers -> 'seen') WITH ORDINALITY AS t(x, ord)
      WHERE x IN ('bruise','skin_tear','burn','swelling_pain','other');
      v_injury_description := v_seen_labels;
    END IF;

    INSERT INTO public.incidents (
      resident_id, facility_id, organization_id, incident_number, category, severity, status,
      occurred_at, discovered_at, shift, location_description, location_type,
      description, immediate_actions,
      fall_witnessed, injury_occurred, injury_severity, injury_description,
      elopement_last_seen_at, elopement_found_at, elopement_found_location, elopement_outcome,
      reported_by, created_by, ahca_reportable, insurance_reportable, regulatory_flags
    ) VALUES (
      v_resident_id, v_facility_id, v_org, v_incident_number, v_category, v_final_level, 'open',
      v_occurred_at, now(), v_shift, COALESCE(v_location_label, 'Not specified'), v_location_code,
      v_sentence || CASE WHEN v_note IS NOT NULL THEN E'\n\nStaff note: ' || v_note ELSE '' END,
      v_immediate_actions,
      CASE WHEN v_kind = 'fall' THEN CASE v_answers ->> 'witnessed' WHEN 'yes' THEN true WHEN 'no' THEN false ELSE NULL END ELSE NULL END,
      v_injury_occurred, v_injury_severity, v_injury_description,
      CASE WHEN v_kind = 'wandering' THEN v_occurred_at ELSE NULL END,
      CASE WHEN v_kind = 'wandering' AND v_where IN ('found_inside','found_grounds','found_off_property') THEN now() ELSE NULL END,
      CASE WHEN v_kind = 'wandering' THEN CASE v_where
        WHEN 'found_inside' THEN 'Inside'
        WHEN 'found_grounds' THEN 'Outside on the grounds'
        WHEN 'found_off_property' THEN 'Off the property'
        ELSE NULL END ELSE NULL END,
      CASE WHEN v_kind = 'wandering' THEN v_where ELSE NULL END,
      v_uid, v_uid,
      COALESCE((v_flags ->> 'ahca_reportable')::boolean, false),
      COALESCE((v_flags ->> 'insurance_reportable')::boolean, false),
      v_flags
    )
    RETURNING id INTO v_incident_id;

    UPDATE public.care_events SET incident_id = v_incident_id WHERE id = v_care_event_id;
    IF v_condition_change_id IS NOT NULL THEN
      UPDATE public.condition_changes SET linked_incident_id = v_incident_id WHERE id = v_condition_change_id;
    END IF;

    -- ---- incident_followups from incident_followup_protocols ---------------
    FOR v_proto IN
      SELECT p.*
      FROM public.incident_followup_protocols p
      WHERE p.is_active
        AND p.deleted_at IS NULL
        AND p.organization_id = v_org
        AND (p.facility_id = v_facility_id OR p.facility_id IS NULL)
        AND (p.kind = v_kind OR p.kind = 'any')
        AND p.min_level <= v_final_level
        AND (p.requires_flag IS NULL OR v_flags ->> p.requires_flag = 'true')
        AND NOT (
          p.facility_id IS NULL
          AND EXISTS (
            SELECT 1 FROM public.incident_followup_protocols q
            WHERE q.is_active AND q.deleted_at IS NULL
              AND q.organization_id = v_org
              AND q.facility_id = v_facility_id
              AND q.task_type = p.task_type
              AND (q.kind = v_kind OR q.kind = 'any')
              AND q.min_level <= v_final_level
              AND (q.requires_flag IS NULL OR v_flags ->> q.requires_flag = 'true')))
      ORDER BY p.due_offset_minutes, p.task_type
    LOOP
      v_assignee := CASE v_proto.assign_to_role
        WHEN 'reporter' THEN v_uid
        WHEN 'caregiver' THEN v_uid
        ELSE NULL END;

      -- Section 3 of the paper form. One task per staff member on that shift at
      -- that facility, never the reporter: the reporter already gave the account
      -- the event is built from, and a witness statement asking them whether they
      -- saw what they just reported is noise on the floor and a false corroboration
      -- on the printed form. The whole rule lives in care_event_sync_witness_tasks
      -- so the administrator's add and remove path creates identical rows (COL-354).
      IF v_proto.task_type = 'witness_statement' THEN
        PERFORM public.care_event_sync_witness_tasks(v_care_event_id);
        CONTINUE;
      END IF;

      IF v_proto.repeat_every_minutes IS NOT NULL AND v_proto.repeat_every_minutes > 0 THEN
        v_offset := v_proto.due_offset_minutes;
        WHILE v_offset <= COALESCE(v_proto.repeat_until_minutes, v_proto.due_offset_minutes) LOOP
          INSERT INTO public.incident_followups (
            incident_id, resident_id, facility_id, organization_id, task_type, description, due_at, assigned_to
          ) VALUES (
            v_incident_id, v_resident_id, v_facility_id, v_org, v_proto.task_type, v_proto.description,
            v_occurred_at + make_interval(mins => v_offset), v_assignee
          );
          v_offset := v_offset + v_proto.repeat_every_minutes;
        END LOOP;
      ELSE
        INSERT INTO public.incident_followups (
          incident_id, resident_id, facility_id, organization_id, task_type, description, due_at, assigned_to
        ) VALUES (
          v_incident_id, v_resident_id, v_facility_id, v_org, v_proto.task_type, v_proto.description,
          v_occurred_at + make_interval(mins => v_proto.due_offset_minutes), v_assignee
        );
      END IF;
    END LOOP;

    -- ---- regulatory_reporting_obligations when the flags say AHCA ----------
    IF COALESCE((v_flags ->> 'ahca_reportable')::boolean, false) THEN
      PERFORM public.care_event_create_ahca_obligations(v_incident_id, v_facility_id, v_org, v_occurred_at, v_tz);
    END IF;

    -- ---- exec_alerts row for the in-app feed (no resident name; entity_id is the legal entity)
    v_level_word := CASE v_level WHEN 2 THEN 'Heads-up' WHEN 3 THEN 'Urgent' ELSE 'Emergency' END;
    v_tile_word := CASE v_kind
      WHEN 'fall' THEN 'Fall'
      WHEN 'injury_found' THEN 'Hurt'
      WHEN 'condition_change' THEN 'Sick or not themselves'
      WHEN 'behavior' THEN 'Upset or behavior'
      WHEN 'wandering' THEN 'Wandering or left'
      WHEN 'medication' THEN 'Medicine'
      WHEN 'family_complaint' THEN 'Family or complaint'
      ELSE 'Building or other' END;
    INSERT INTO public.exec_alerts (
      organization_id, source_module, severity, title, body, entity_id, facility_id,
      deep_link_path, category, status
    ) VALUES (
      v_org, 'incidents',
      (CASE v_level WHEN 2 THEN 'info' WHEN 3 THEN 'warning' ELSE 'critical' END)::exec_alert_severity,
      v_level_word || ' ' || v_tile_word, v_incident_number,
      (SELECT f.entity_id FROM public.facilities f WHERE f.id = v_facility_id), v_facility_id,
      '/admin/care-events/' || v_care_event_id::text, 'care_event', 'open'
    );

    -- ---- deliveries: step rows whose after_minutes = 0 ----------------------
    FOR v_policy IN
      SELECT * FROM public.care_event_applicable_policies(v_org, v_facility_id, v_final_level)
      WHERE after_minutes = 0
      ORDER BY step
    LOOP
      PERFORM public.care_event_expand_targets(v_care_event_id, v_policy.id);
    END LOOP;
  END IF;

  RETURN public.care_event_receipt(v_care_event_id, false);
END;
$function$;


CREATE OR REPLACE FUNCTION haven.role_tier(p_role public.app_role)
 RETURNS integer LANGUAGE sql IMMUTABLE SET search_path TO ''
AS $function$ SELECT CASE p_role WHEN 'owner' THEN 100 WHEN 'org_admin' THEN 90 WHEN 'facility_admin' THEN 80 WHEN 'manager' THEN 70 WHEN 'coordinator' THEN 60 WHEN 'admin_assistant' THEN 50 WHEN 'med_tech' THEN 50 WHEN 'nurse' THEN 50 WHEN 'dietary' THEN 40 WHEN 'cook' THEN 40 WHEN 'maintenance_role' THEN 40 WHEN 'broker' THEN 30 WHEN 'housekeeper' THEN 30 WHEN 'caregiver' THEN 20 WHEN 'dietary_aide' THEN 20 WHEN 'family' THEN 10 ELSE 0 END $function$;


-- Role-keyed configuration: nurse moves to med_tech (merged, never narrowed); cook copies dietary.
INSERT INTO public.role_permissions(app_role, feature, permission_level, description)
SELECT 'med_tech', n.feature, n.permission_level, n.description FROM public.role_permissions n
WHERE n.app_role = 'nurse' AND NOT EXISTS (SELECT 1 FROM public.role_permissions m WHERE m.app_role = 'med_tech' AND m.feature = n.feature);
DELETE FROM public.role_permissions WHERE app_role = 'nurse';
INSERT INTO public.role_permissions(app_role, feature, permission_level, description)
SELECT 'cook', d.feature, d.permission_level, d.description FROM public.role_permissions d
WHERE d.app_role = 'dietary' AND NOT EXISTS (SELECT 1 FROM public.role_permissions c WHERE c.app_role = 'cook' AND c.feature = d.feature);

UPDATE public.search_tool_policies m SET enabled = m.enabled OR n.enabled, updated_at = now()
FROM public.search_tool_policies n
WHERE m.app_role = 'med_tech' AND n.app_role = 'nurse' AND n.organization_id = m.organization_id AND n.tool_name = m.tool_name;
INSERT INTO public.search_tool_policies(organization_id, tool_name, tool_tier, app_role, enabled)
SELECT n.organization_id, n.tool_name, n.tool_tier, 'med_tech', n.enabled FROM public.search_tool_policies n
WHERE n.app_role = 'nurse' AND NOT EXISTS (SELECT 1 FROM public.search_tool_policies m
  WHERE m.app_role = 'med_tech' AND m.organization_id = n.organization_id AND m.tool_name = n.tool_name);
DELETE FROM public.search_tool_policies WHERE app_role = 'nurse';
INSERT INTO public.search_tool_policies(organization_id, tool_name, tool_tier, app_role, enabled)
SELECT d.organization_id, d.tool_name, d.tool_tier, 'cook', d.enabled FROM public.search_tool_policies d
WHERE d.app_role = 'dietary' AND NOT EXISTS (SELECT 1 FROM public.search_tool_policies c
  WHERE c.app_role = 'cook' AND c.organization_id = d.organization_id AND c.tool_name = d.tool_name);

-- Arrays: replace nurse, keep order, drop the duplicate if med_tech was already listed; add cook beside dietary.
CREATE FUNCTION pg_temp.role_list_swap(p text[]) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT array_agg(r ORDER BY o) FROM (
    SELECT DISTINCT ON (r) r, o FROM (
      SELECT CASE WHEN e = 'nurse' THEN 'med_tech' ELSE e END r, o * 2 o FROM unnest(p) WITH ORDINALITY u(e, o)
      UNION ALL SELECT 'cook', o * 2 + 1 FROM unnest(p) WITH ORDINALITY u(e, o) WHERE e = 'dietary'
    ) s ORDER BY r, o) d
$$;
UPDATE public.flow_workflow_definitions SET roles_allowed = pg_temp.role_list_swap(roles_allowed)
  WHERE roles_allowed && ARRAY['nurse','dietary'];
UPDATE public.documents SET role_tags = pg_temp.role_list_swap(role_tags)
  WHERE role_tags && ARRAY['nurse','dietary'];
UPDATE public.assessment_templates SET required_role = pg_temp.role_list_swap(required_role::text[])::public.app_role[]
  WHERE required_role && ARRAY['nurse','dietary']::public.app_role[];

-- The nurse login(s) become med_tech. The profile row is what the token hook reads.
UPDATE auth.users u SET raw_app_meta_data = coalesce(u.raw_app_meta_data, '{}'::jsonb) || jsonb_build_object('app_role', 'med_tech')
  FROM public.user_profiles p WHERE p.id = u.id AND p.app_role = 'nurse';
UPDATE public.user_profiles SET app_role = 'med_tech', updated_at = now() WHERE app_role = 'nurse';

DO $check$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_policies WHERE (coalesce(qual,'')||coalesce(with_check,'')) ~ '''nurse''') THEN
    RAISE EXCEPTION 'A policy still names nurse';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname IN ('public','haven') AND p.prosrc ~ '''nurse''' AND p.proname <> 'role_tier') THEN
    RAISE EXCEPTION 'A function still names nurse';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_profiles WHERE app_role = 'nurse' AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'A nurse login remains';
  END IF;
END
$check$;

NOTIFY pgrst, 'reload schema';
COMMIT;
